/* Detailed individual NCERT-aligned Biology notes for Classes XI–XII.
   Each chapter includes explanatory sections, process/diagram guides, exam traps and recall prompts. */
(function () {
  "use strict";
  const make = (level, chapter, intro, sections, keyFacts, workedExamples, commonMistakes, examFocus, recall, glossary, subject = "Biology") => ({
    level, subject, chapter, intro,
    sections: sections.map(([heading, body]) => ({ heading, body })),
    formulas: [],
    formulaCheatSheet: keyFacts.map((fact) => ({formula:fact.label,meaning:fact.meaning,when:fact.when||"Concept recall and application.",units:"Biological terminology/process.",trap:fact.trap||"Match the structure/process to the exact question wording."})),
    points: sections.map(([heading, body]) => heading + ": " + body.split(/[.!?]/)[0] + "."),
    example: workedExamples.length ? workedExamples[0].steps.join(" ") : "Use the process summary and diagram labels as a starting point, then practise the prescribed textbook questions.",
    workedExamples, commonMistakes, examFocus, recall, glossary,
    depth: "detailed",
    sourceNote: "Original, chapter-specific explanatory Biology notes aligned to commonly taught NCERT concepts. They do not reproduce textbook passages. Confirm the prescribed edition and official CBSE/NTA scope; diagrams are described in words and should be practised from the textbook."
  });
  const notes = [
    make("Class 11","The Living World",
      "Understand what counts as living, why classification is needed, how nomenclature works and how taxonomic collections support identification.",
      [
        ["Living characteristics","Living systems show cellular organisation, metabolism and the capacity to maintain and reproduce organised systems. No single outward feature perfectly separates every living from non-living object: growth can occur outside organisms too, while reproduction is not possible for every individual. Metabolism—the total of chemical reactions in an organism—is a useful defining feature when considered with cellular organisation and regulated activity."],
        ["Taxonomy and systematics","Taxonomy includes identification, nomenclature and classification; systematics additionally considers evolutionary relationships. Classification groups organisms using shared characters and evidence. As molecular and ecological evidence improves, relationships and classifications may be revised. A useful answer explains the basis of a grouping rather than only stating the name of a rank."],
        ["Binomial nomenclature","Scientific naming uses two parts: the genus name followed by the specific epithet. Genus begins with a capital letter, specific epithet with a lowercase letter, and the full name is italicised in print (underlined separately when handwritten). Authorship may be appended in formal usage. A common name may vary by region; a scientific name is designed to communicate consistently."],
        ["Taxonomic aids","Herbaria preserve pressed, labelled plant specimens; botanical gardens maintain living collections; museums preserve representative specimens; zoological parks maintain living animals under care. Keys identify organisms through paired contrasting statements. Flora describes plants of an area, manuals help identify names, and monographs treat a group comprehensively. Labels and locality/date data are scientifically important, not decorative."]
      ],
      [{label:"Taxonomic hierarchy",meaning:"Species → genus → family → order → class → phylum/division → kingdom.",trap:"Lower ranks generally contain fewer, more similar organisms."},{label:"Binomial name",meaning:"Genus + specific epithet; italicise both words.",trap:"Capitalise genus, not the specific epithet."}],
      [{title:"Use a key",steps:["Observe the specimen and identify the first pair of contrasting features.","Choose the statement matching the specimen and follow its reference.","Continue until the key reaches an identification.","Do not skip a branch because a common name seems familiar." ]},{title:"Classify evidence",steps:["State the character used for grouping.","Explain how it is shared by the members.","Compare it with a distinguishing character in another group.","Avoid claiming one visible feature proves every evolutionary relationship." ]}],
      ["Calling all individual organisms reproductively capable.","Using informal common names as though globally unique.","Capitalising both words in a standard binomial name.","Confusing taxonomy with only the naming of organisms."],
      ["NEET emphasis: hierarchy order, nomenclature rules and the function of each taxonomic aid."],
      ["Why is metabolism informative when identifying living systems?","What two parts form a binomial name?","How does a key support identification?"],
      ["Taxonomy: identification, naming and classification.","Systematics: study of diversity and relationships.","Herbarium: collection of preserved plant specimens."]),
    make("Class 11","Biological Classification",
      "Compare major biological classification systems, prokaryotes/eukaryotes, kingdoms, viruses and other acellular agents.",
      [
        ["Why classifications change","Classification systems organise biological diversity and reflect the evidence available. The five-kingdom approach considers cell structure, body organisation, nutrition, reproduction and evolutionary relationships, but modern phylogeny uses molecular data to clarify relationships. A classification is a model of relationships, not just a list of easily observed shapes."],
        ["Monera and Protista","Bacteria are prokaryotic: they lack a membrane-bound nucleus and typical membrane-bound organelles. Their cell walls and metabolism vary widely. Protists are diverse mostly unicellular eukaryotes, including photosynthetic and heterotrophic forms. Cell type, nutrition, locomotion and life cycle are useful comparisons; avoid assuming every member of a broad kingdom looks or feeds the same way."],
        ["Fungi and other kingdoms","Fungi are heterotrophs that generally absorb nutrients after extracellular digestion; many have chitin-containing walls. Plants mainly photosynthesise and have cellulose walls; animals ingest food and lack cell walls. Fungi may be unicellular or multicellular and reproduce by varied spores. Lichens are associations of a fungus with a photosynthetic partner; mycorrhizae associate fungi with plant roots."],
        ["Viruses, viroids and prions","Viruses have nucleic acid enclosed in a protein capsid and reproduce only using a host's cellular machinery. Their genome may be DNA or RNA; the host and replication strategy matter. Viroids are small infectious RNA agents without a protein coat, primarily associated with plants. Prions are infectious misfolded proteins. They do not fit neatly into ordinary cellular-kingdom categories."]
      ],
      [{label:"Prokaryote vs eukaryote",meaning:"Nucleoid region without a membrane-bound nucleus vs a membrane-bound nucleus.",trap:"Both cell types contain ribosomes and genetic material."},{label:"Virus structure",meaning:"Genome + capsid; some viruses also carry an envelope.",trap:"A virus does not reproduce independently like a cell."}],
      [{title:"Classify an organism from clues",steps:["Check for a true nucleus and membrane-bound organelles.","Identify nutrition mode and cell-wall features.","Use reproduction and body organisation as further evidence.","Compare all clues; do not classify solely by habitat." ]},{title:"Separate acellular agents",steps:["A virus has a nucleic-acid genome within a capsid.","A viroid is infectious RNA without a protein capsid.","A prion is an infectious protein form.","Use the specific defining component asked in the question." ]}],
      ["Assuming all bacteria are harmful.","Treating fungi as photosynthetic because they are non-animal organisms.","Saying viruses contain both DNA and RNA as their genome in the usual simple description.","Confusing viroid with prion."],
      ["NEET focus: kingdom-character contrasts, wall composition, nutrition, virus components and symbiotic associations."],
      ["What distinguishes a prokaryotic cell?","How do fungi obtain nutrition?","How are viroids different from prions?"],
      ["Capsid: protein coat enclosing a viral genome.","Mycorrhiza: plant-root/fungus association.","Viroid: small infectious RNA agent lacking a capsid."]),
    make("Class 11","Plant Kingdom",
      "Compare algae, bryophytes, pteridophytes, gymnosperms and angiosperms through body organisation, vascular tissues, seeds and life-cycle dominance.",
      [
        ["Algae and bryophytes","Algae range from unicellular to multicellular photosynthetic forms and inhabit aquatic or moist environments. Bryophytes lack the true vascular tissues of higher plants and commonly need water for sperm movement during sexual reproduction. Their gametophyte is dominant; the sporophyte remains attached or nutritionally dependent in the typical textbook description."],
        ["Pteridophytes","Pteridophytes possess true roots, stems, leaves and vascular tissue but reproduce by spores rather than seeds. The sporophyte is the conspicuous dominant generation. Spores germinate into gametophytes; fertilisation still depends on water in typical examples. Homospory produces one spore type; heterospory produces microspores and megaspores, an important evolutionary step toward seed habit."],
        ["Gymnosperms and angiosperms","Gymnosperms form seeds not enclosed within an ovary-derived fruit; their reproductive structures often include cones. Angiosperms produce flowers and seeds enclosed in fruits. Double fertilisation in angiosperms forms the zygote and endosperm-forming product. Seeds protect the embryo and can support dormancy and dispersal."],
        ["Alternation of generations","The life cycle alternates between haploid gametophyte and diploid sporophyte. Meiosis produces haploid spores; gametes fuse at fertilisation to restore diploidy. Ask which generation produces spores and which produces gametes. The conspicuous plant body does not tell you the ploidy unless the group/life-cycle stage is identified."]
      ],
      [{label:"Bryophytes",meaning:"Non-vascular plants with dominant gametophyte in the common life-cycle description.",trap:"They are not simply 'algae on land'."},{label:"Pteridophytes",meaning:"Vascular, seedless plants whose sporophyte is dominant.",trap:"They reproduce through spores, not seeds."},{label:"Angiosperm double fertilisation",meaning:"Syngamy plus triple fusion in the typical embryo-sac pattern.",trap:"These are two distinct fusion events."}],
      [{title:"Compare plant groups",steps:["Check whether true vascular tissue is present.","Check if the plant reproduces by spores or seeds.","If seeds occur, determine whether they are enclosed in an ovary-derived fruit.","Use generation dominance and reproductive structures as additional criteria." ]},{title:"Track ploidy",steps:["Sporophyte is diploid and produces haploid spores by meiosis.","Spores grow into haploid gametophytes.","Gametophytes produce haploid gametes by mitosis in the standard cycle.","Fertilisation produces a diploid zygote that develops into sporophyte." ]}],
      ["Confusing sporophyte and gametophyte dominance.","Treating gymnosperm seeds as enclosed in fruits.","Saying pteridophytes form seeds.","Mixing spore formation with gamete fusion."],
      ["NEET focus: characteristic examples, vascular tissue, seed/fruit status and life-cycle stage diagrams."],
      ["Which group has vascular tissue but no seeds?","What does double fertilisation produce?","Which generation produces haploid spores?"],
      ["Gametophyte: haploid generation producing gametes.","Sporophyte: diploid generation producing spores.","Heterospory: production of two different spore types."]),
    make("Class 11","Animal Kingdom",
      "Compare animal phyla by body symmetry, organisation, germ layers, coelom, segmentation and defining structural traits.",
      [
        ["Levels of organisation and symmetry","Animals may show cellular, tissue, organ or organ-system levels of organisation. Asymmetry means no regular body plane divides the body into similar halves; radial symmetry allows multiple planes around an axis; bilateral symmetry gives right/left halves around one plane. Symmetry relates to body plan and lifestyle but should be used with other characters."],
        ["Germ layers and body cavity","Diploblastic animals develop two primary germ layers; triploblastic animals develop three. A coelom is a body cavity lined by mesoderm; acoelomates lack it, pseudocoelomates have a cavity not fully lined by mesoderm, and coelomates have a true coelom. Body cavity supports organ placement and movement but is only one comparison criterion."],
        ["Segmentation and support","Segmentation divides the body into repeated units, sometimes with specialised segments. Exoskeletons provide support/protection externally; endoskeletons provide support internally. Appendages, notochord/vertebral column, jointed legs, water vascular system and body covering can be diagnostic at phylum level."],
        ["Classification by combined characters","Porifera have porous bodies and water flow; cnidarians have specialised stinging cells; flatworms are dorsoventrally flattened; annelids are segmented; arthropods have jointed appendages and chitinous exoskeleton; molluscs typically have a mantle/foot; echinoderms possess a water vascular system and are mostly marine; chordates possess a notochord at least during some developmental stage. Use combinations, not a single broad clue."]
      ],
      [{label:"Triploblastic",meaning:"Three germ layers: ectoderm, mesoderm and endoderm.",trap:"Germ-layer count is distinct from body cavity."},{label:"True coelom",meaning:"Body cavity fully lined by mesoderm.",trap:"A fluid-filled cavity alone does not establish a true coelom."},{label:"Chordate hallmark",meaning:"Notochord at some stage, with other chordate features in the standard description.",trap:"The notochord need not persist in the adult of all chordates."}],
      [{title:"Identify the likely phylum",steps:["Read every stated characteristic—symmetry, segmentation, skeleton and key structure.","Match the most diagnostic feature first, such as jointed appendages or water vascular system.","Check that the remaining traits do not contradict the candidate.","Answer with the defining evidence rather than only naming a group." ]},{title:"Classify a body cavity",steps:["Determine whether a cavity exists between body wall and gut.","Check whether mesoderm fully lines it.","Classify as acoelomate, pseudocoelomate or coelomate under the textbook definitions.","Do not infer cavity type from segmentation alone." ]}],
      ["Classifying an animal only by habitat.","Confusing pseudocoelom with a true coelom.","Calling every marine animal an echinoderm.","Treating adult body appearance as the only chordate criterion."],
      ["NEET focus: phylum examples and distinguishing characteristics, especially symmetry, segmentation, appendages and body cavity."],
      ["What feature is distinctive of arthropods?","What is a true coelom?","What is the role of a notochord in classification?"],
      ["Diploblastic: possessing two primary germ layers.","Coelom: body cavity lined by mesoderm.","Notochord: flexible axial support structure in chordates."]),
    make("Class 11","Morphology of Flowering Plants",
      "Identify root, stem, leaf, inflorescence, flower, fruit and seed structures by their origin and function.",
      [
        ["Root and stem systems","The root commonly anchors the plant and absorbs water/minerals; modifications include storage, support, respiration or parasitic attachment. Stems bear nodes, internodes, leaves and buds; modifications include tubers, rhizomes, tendrils and thorns. Origin matters: a potato tuber is a modified stem, whereas sweet potato storage roots are modified roots."],
        ["Leaves and phyllotaxy","A typical leaf has leaf base, petiole and lamina; venation may be reticulate or parallel in common textbook contrasts. Phyllotaxy describes leaf arrangement—alternate, opposite or whorled. Leaves may be modified into spines, tendrils, storage structures or insect-trapping organs; identify the organ's origin before naming the adaptation."],
        ["Inflorescence and flower","Inflorescence describes how flowers are arranged on the axis. A flower's typical whorls are calyx, corolla, androecium and gynoecium; each contributes to protection, attraction or reproduction. A complete/bisexual/actinomorphic description uses distinct criteria—do not treat these terms as synonyms."],
        ["Fruit and seed","A fruit generally develops from the ovary after fertilisation; accessory parts can contribute in some cases. A seed contains the embryo and protective seed coat, and may store food in endosperm or cotyledons depending on species. A monocot/dicot distinction often uses cotyledon number but should be combined with additional characters when required."]
      ],
      [{label:"Root vs stem modification",meaning:"Classify by origin and structure, then identify adaptive function.",trap:"An aerial shape does not guarantee stem origin."},{label:"Flower whorls",meaning:"Calyx, corolla, androecium, gynoecium.",trap:"A flower may be incomplete or unisexual."}],
      [{title:"Identify a modification",steps:["Describe the visible structure and its attachment to the plant.","Determine whether it is a root, stem or leaf based on origin/features.","Link the structural change to storage, support, defence or reproduction.","Use the textbook example only after the structure-function reasoning." ]},{title:"Compare floral terms",steps:["Actinomorphic: several planes can divide into similar halves; zygomorphic: one plane.","Bisexual: both male and female reproductive parts; unisexual: one type.","Complete: all four typical whorls present; incomplete: one or more absent.","These labels describe separate axes of classification." ]}],
      ["Confusing root tubers with stem tubers.","Calling every flower bisexual.","Confusing inflorescence with a single flower.","Using fruit type without checking the source tissue."],
      ["NEET focus: plant-modification examples, floral formula/diagram labels, placentation and fruit/seed structures."],
      ["How do root and stem tubers differ?","What does phyllotaxy describe?","Why are complete and bisexual not equivalent?"],
      ["Phyllotaxy: arrangement of leaves on a stem.","Placentation: arrangement of ovules within the ovary.","Lamina: leaf blade."]),
    make("Class 11","Anatomy of Flowering Plants",
      "Compare plant tissue systems and the internal arrangement of vascular tissues in roots, stems and leaves.",
      [
        ["Meristematic and permanent tissues","Meristems contain actively dividing cells and support growth at apices or laterally. Permanent tissues differentiate into protective, ground, mechanical or conducting functions. Simple tissues include parenchyma, collenchyma and sclerenchyma; complex vascular tissues include xylem and phloem. Cell-wall thickness, living status and arrangement explain much of their role."],
        ["Epidermal and ground systems","The epidermis protects, reduces water loss, and includes stomata or specialised structures. Ground tissues support photosynthesis, storage and strengthening. Stomata have guard cells controlling aperture; roots often have root hairs that increase absorption surface. Identify a tissue by both location and cell properties."],
        ["Xylem and phloem","Xylem transports water/mineral ions and often contributes mechanical support; its elements include tracheids, vessels, fibres and parenchyma. Phloem distributes sugars and other organic solutes through sieve elements/tubes, companion cells and supporting cells depending on the plant. Transport direction depends on source-sink relations, so phloem movement should not be described as always downward."],
        ["Dicot/monocot and secondary growth","Typical dicot and monocot roots/stems differ in vascular-bundle arrangement and cambium pattern. A common dicot stem arrangement has vascular bundles in a ring and cambium supporting secondary growth; typical monocot stems have scattered bundles and usually lack the same secondary-growth pattern. These are textbook-level generalisations, so use the exact organ and sample shown."]
      ],
      [{label:"Xylem",meaning:"Water/mineral transport and structural support.",trap:"Transport and support roles overlap but differ by cell type."},{label:"Phloem",meaning:"Translocation of sugars and other organic solutes from sources to sinks.",trap:"The direction is not universally downward."},{label:"Secondary growth",meaning:"Increase in girth through lateral meristems such as vascular cambium.",trap:"Not equally developed in all monocots/dicots."}],
      [{title:"Read a tissue diagram",steps:["Orient the section and identify whether it is root, stem or leaf.","Locate epidermis, ground tissue and vascular bundles.","Compare xylem/phloem positions and bundle arrangement.","Use multiple diagnostic characters instead of a single visual clue." ]},{title:"Explain water transport",steps:["Root hairs increase the contact surface for uptake.","Water enters through water-potential gradients.","Xylem conducts water toward leaves with transpiration contributing to upward pull.","Explain roles without claiming xylem is solely driven by root pressure." ]}],
      ["Swapping xylem and phloem.","Confusing permanent tissue with meristem.","Assuming every monocot/dicot specimen follows a simplified diagram exactly.","Treating stomata as the only surface structure."],
      ["NEET focus: tissue function, labelled cross-sections, vascular-bundle differences and cell-wall features."],
      ["Which tissue conducts sugar?","What does vascular cambium do?","Why do root hairs increase water uptake?"],
      ["Meristem: actively dividing tissue.","Lateral meristem: meristem supporting increase in girth.","Translocation: movement of organic solutes through phloem."]),
    make("Class 11","Structural Organisation in Animals",
      "Use epithelial, connective, muscular and nervous tissues to explain organ structure and function.",
      [
        ["Epithelial tissue","Epithelia cover surfaces and line cavities. Cells are closely packed with little extracellular matrix; classification considers shape and number of layers. Simple squamous epithelium supports diffusion, cuboidal cells often support secretion/absorption, columnar cells line many digestive regions, and ciliated epithelium moves material. Structure follows function, but cell type should be tied to the organ context."],
        ["Connective tissue","Connective tissue has cells embedded in extracellular matrix; matrix composition controls flexibility, resistance or fluid transport. Areolar tissue fills spaces, adipose stores energy and insulates, cartilage provides flexible support, bone provides rigid support, blood transports materials, and tendons/ligaments connect distinct structures. Tendons connect muscle to bone; ligaments connect bone to bone in standard descriptions."],
        ["Muscle and nervous tissues","Skeletal muscle is striated and generally voluntary; cardiac muscle is striated, branching and involuntary; smooth muscle is non-striated and involuntary. Neurons receive and transmit signals through dendrites, cell body and axon. Synapses enable communication between cells. Do not confuse a muscle's voluntary classification with whether it is striated."],
        ["From tissue to organ","Organs combine several tissues into an integrated role. In a practical or diagram question, identify the tissue's morphology, position and function. Blood is connective tissue despite being fluid because cells are suspended in plasma. A neuron is specialised for signalling, while supporting glial cells maintain the nervous environment."]
      ],
      [{label:"Tendon vs ligament",meaning:"Tendon connects muscle to bone; ligament connects bone to bone.",trap:"Both are dense connective tissues, but their attachments differ."},{label:"Muscle types",meaning:"Skeletal: striated/usually voluntary; cardiac: striated/involuntary; smooth: non-striated/involuntary.",trap:"Striation and voluntary control are separate properties."}],
      [{title:"Identify tissue from function",steps:["Rapid diffusion across a thin barrier suggests simple squamous epithelium.","Flexible support suggests cartilage; hard mineralised support suggests bone.","Impulse transmission suggests nervous tissue.","Check location and cell properties before making the identification." ]},{title:"Classify a connection",steps:["Muscle attaching to bone uses a tendon.","Bone-to-bone stabilisation uses a ligament.","Both transmit force but differ in attachment and mechanical role.","State the exact structures connected." ]}],
      ["Calling blood a non-tissue because it is fluid.","Confusing tendon and ligament.","Saying all muscle is voluntary.","Assuming every epithelium has multiple layers."],
      ["NEET focus: tissue type-function-location matching and structural distinctions."],
      ["What is the function of cilia in epithelium?","Which connective tissue transports materials?","How are skeletal and cardiac muscle different?"],
      ["Extracellular matrix: material outside cells that helps determine connective-tissue properties.","Neuron: excitable cell transmitting signals.","Synapse: junction where cells communicate."]),
    make("Class 11","Cell: The Unit of Life",
      "Compare prokaryotic and eukaryotic cells and link membranes, organelles, cytoskeleton and genetic material to function.",
      [
        ["Cell theory and size","Cells are the basic structural and functional units of organisms. Cell size is limited by exchange demands and geometry; a large cell has less surface area relative to its volume than a small cell of the same shape. Surface-to-volume reasoning helps explain folded membranes, organelle compartmentalisation and specialised shapes."],
        ["Membrane and nucleus","The plasma membrane is a selectively permeable lipid bilayer with proteins; transport depends on concentration/electrochemical gradients and available proteins. Eukaryotic cells enclose DNA within a nuclear envelope containing pores, while prokaryotic DNA occupies a nucleoid region. Both have ribosomes; a nucleus is not required for protein synthesis."],
        ["Organelles","Mitochondria support aerobic energy conversion; chloroplasts perform photosynthetic energy conversion in plants/algae; rough ER supports synthesis/processing of many membrane/secreted proteins; smooth ER participates in lipid synthesis and detoxification; Golgi modifies/sorts packages; lysosomes digest materials; peroxisomes process certain oxidative reactions. These organelles interact as a system."],
        ["Cytoskeleton, ribosomes and cell surfaces","Microtubules, microfilaments and intermediate filaments provide shape, transport tracks and movement. Ribosomes translate mRNA into polypeptides; free and ER-bound ribosomes differ primarily by the destination of the proteins made. Cell walls, plasmodesmata, cilia and flagella are specialised structures found in appropriate cell types."]
      ],
      [{label:"Ribosome",meaning:"Site of protein synthesis by translation.",trap:"Ribosomes occur in both prokaryotes and eukaryotes."},{label:"Mitochondrion",meaning:"Major site of aerobic ATP generation in eukaryotic cells.",trap:"It is not the only metabolic site in the cell."},{label:"Golgi apparatus",meaning:"Modifies, sorts and packages many cellular products.",trap:"Do not confuse it with the ER's initial synthesis roles."}],
      [{title:"Trace a secreted protein",steps:["A gene is transcribed to mRNA in the nucleus in a typical eukaryotic cell.","A ribosome associated with rough ER translates the mRNA.","Protein enters ER for folding/initial processing, then vesicles deliver it to Golgi.","Golgi-sorted vesicles transport the product toward secretion." ]},{title:"Classify a cell",steps:["Check for a membrane-bound nucleus and membrane-bound organelles.","Check DNA location and ribosome type if described.","Cell wall or chloroplast may be helpful but are not sufficient alone.","Use more than one feature to distinguish a prokaryote/eukaryote." ]}],
      ["Saying prokaryotes have no ribosomes.","Confusing ER and Golgi functions.","Assuming all eukaryotic cells contain chloroplasts.","Treating an organelle list as unrelated facts rather than a pathway."],
      ["NEET focus: organelle-function matching, membrane transport and prokaryote/eukaryote comparisons."],
      ["What is the role of ribosomes?","How does a secreted protein move through the endomembrane system?","Why does surface-to-volume ratio matter?"],
      ["Nucleoid: DNA-containing region in a prokaryote.","Selective permeability: membrane controls movement of substances.","Cytoskeleton: internal protein framework of a cell."]),
    make("Class 11","Biomolecules",
      "Connect chemical bonds and molecular structure to carbohydrate, lipid, protein, nucleic-acid and enzyme function.",
      [
        ["Monomers and polymers","Many biological macromolecules are formed by linking smaller units, but not every large biological molecule is a polymer in the same way. Monosaccharides form glycosidic linkages in carbohydrates; amino acids form peptide bonds in proteins; nucleotides connect by phosphodiester bonds in nucleic acids. The bond type predicts which enzymes can hydrolyse the molecule."],
        ["Carbohydrates and lipids","Carbohydrates provide energy, storage and structural material; simple sugars can be linked into polysaccharides with different branching and properties. Lipids are hydrophobic or amphipathic and include fats, phospholipids and steroids. Triglycerides store energy efficiently; phospholipids form bilayers because they have hydrophilic heads and hydrophobic tails."],
        ["Proteins and nucleic acids","A protein's amino-acid sequence influences folding and function. Hydrogen bonds, ionic interactions, hydrophobic interactions and disulfide bonds can contribute to structure. DNA stores genetic information; RNA has roles in expression/regulation and catalysis in some systems. Nucleotides contain sugar, nitrogenous base and phosphate; nucleosides lack phosphate."],
        ["Enzymes and metabolism","Enzymes lower activation energy and speed reactions without being consumed overall. Activity depends on substrate, concentration, temperature, pH and inhibitors; extremes can disrupt structure. Enzymes affect rate and equilibrium is reached faster, but a catalyst does not change the thermodynamic equilibrium constant. Cofactors/coenzymes may be required for particular reactions."]
      ],
      [{label:"Major biomolecular bonds",meaning:"Glycosidic (carbohydrate), peptide (protein), phosphodiester (nucleic acid).",trap:"Identify the molecule and bond asked."},{label:"Nucleotide vs nucleoside",meaning:"Nucleotide = sugar + base + phosphate; nucleoside = sugar + base.",trap:"Phosphate is the distinguishing component."}],
      [{title:"Identify a biomolecule",steps:["Look for the building block or linkage named in the question.","A peptide bond signals amino-acid residues in a polypeptide.","A phosphodiester bond connects nucleotides along a nucleic-acid backbone.","A glycosidic bond commonly links carbohydrate units." ]},{title:"Explain enzyme denaturation",steps:["Identify the temperature/pH change beyond the protein's suitable range.","Interactions maintaining the active conformation are disrupted.","The active site's shape/chemistry changes and reaction rate may fall.","Do not claim every enzyme immediately denatures at the same temperature." ]}],
      ["Calling a nucleoside a nucleotide.","Saying enzymes change the equilibrium constant.","Treating all lipids as polymers built from repeating monomers.","Assuming every protein denatures at the same condition."],
      ["NEET focus: bond-to-biomolecule mapping, structural levels of proteins and enzyme activity variables."],
      ["Which bond links amino acids?","What component distinguishes nucleotide from nucleoside?","How do enzymes affect activation energy?"],
      ["Monomer: small subunit that can be linked into larger structures.","Peptide bond: linkage between amino acids.","Cofactor: non-protein component required by some enzymes."]),
    make("Class 11","Cell Cycle and Cell Division",
      "Track chromosome number, DNA content and the purpose of mitosis versus meiosis through each cell-cycle phase.",
      [
        ["Cell-cycle phases","Interphase includes G₁ growth, S-phase DNA replication and G₂ preparation. DNA replication doubles DNA amount but does not by itself double chromosome number under centromere-based counting. M phase includes nuclear division and usually cytokinesis. Some cells enter a non-dividing G₀ state."],
        ["Mitosis","Prophase condenses chromosomes, spindle forms and the nuclear envelope changes; metaphase aligns chromosomes; anaphase separates sister chromatids; telophase rebuilds nuclei. Cytokinesis divides cytoplasm. Mitosis normally produces daughter cells maintaining chromosome number, supporting growth, repair and asexual reproduction."],
        ["Meiosis I and II","Meiosis I is the reduction division where homologous chromosomes pair and then separate; crossing over occurs during prophase I in the standard description. Meiosis II separates sister chromatids, resembling mitosis. DNA replicates once before meiosis and does not replicate again between the two divisions."],
        ["Variation and chromosome bookkeeping","Independent assortment and recombination contribute variation. Track ploidy and DNA content separately: chromosome count, chromatid count and DNA mass are not interchangeable. A diploid cell with 2n chromosomes yields haploid products after meiosis if segregation is normal, but nondisjunction can alter outcomes."]
      ],
      [{label:"Mitosis",meaning:"One nuclear division typically maintaining chromosome number.",trap:"DNA replicates before mitosis in S phase."},{label:"Meiosis I",meaning:"Homologous chromosomes separate; chromosome set is reduced.",trap:"Sister chromatids separate in meiosis II."},{label:"Crossing over",meaning:"Exchange between non-sister chromatids of homologous chromosomes in prophase I.",trap:"Do not place it in metaphase or ordinary mitosis."}],
      [{title:"Track a diploid cell",steps:["Start with 2n=8 before S phase.","After S phase, chromosome number remains 8 by centromere count, but DNA content doubles.","After meiosis I, each daughter has n=4 chromosomes still composed of sister chromatids.","After meiosis II, chromatids separate and haploid products have n=4." ]},{title:"Compare divisions",steps:["Mitosis separates sister chromatids in one division.","Meiosis I separates homologues after pairing/recombination.","Meiosis II separates sister chromatids.","Connect each process to its goal: cell maintenance versus gamete/spore chromosome reduction." ]}],
      ["Calling S phase a chromosome-number doubling event.","Saying crossing over occurs in meiosis II.","Forgetting meiosis has two divisions after one replication.","Counting chromatids and chromosomes as the same quantity."],
      ["NEET focus: phase sequence, chromosome count, synapsis/crossing-over and mitosis/meiosis differences."],
      ["When do homologous chromosomes separate?","How many times does DNA replicate before meiosis?","Why does meiosis generate variation?"],
      ["Ploidy: number of chromosome sets.","Synapsis: pairing of homologous chromosomes.","Cytokinesis: division of cytoplasm."]),
    make("Class 11","Transport in Plants",
      "Explain water potential, osmosis, xylem transport, phloem translocation and stomatal regulation through gradients and pressure.",
      [
        ["Water potential and osmosis","Water moves from higher water potential to lower water potential across a selectively permeable membrane under the relevant conditions. Solute addition generally lowers water potential; pressure can raise it. Osmosis is not simply water moving toward 'more concentrated' material in every complex setup—compare water potential and membrane permeability."],
        ["Pathways in roots","Water may move through apoplast (cell walls/intercellular spaces), symplast (cytoplasm through plasmodesmata) and transmembrane pathways. The Casparian strip in endodermis interrupts free apoplastic flow and helps regulate entry into the stele. Root hairs increase surface area for absorption."],
        ["Xylem and transpiration pull","Evaporation from leaf surfaces creates tension that can pull a continuous water column up xylem; cohesion between water molecules and adhesion to xylem walls support this mechanism. Root pressure may contribute under some circumstances but does not account for all ascent in tall plants. Stomata regulate water loss and CO₂ entry simultaneously."],
        ["Phloem translocation","Sugars are loaded into sieve elements at sources and unloaded at sinks. Osmotic water movement changes pressure and supports bulk flow from source toward sink. Source/sink status can vary with growth stage: a storage organ can import sugar at one time and export it later. Phloem transport is not universally downward."]
      ],
      [{label:"Water potential",meaning:"Predicts direction of water movement; water flows down the water-potential gradient.",trap:"State the reference/sign convention used in the course."},{label:"Transpiration pull",meaning:"Water loss from leaves generates tension transmitted through xylem.",trap:"Cohesion/adhesion and a continuous water column matter."},{label:"Source and sink",meaning:"Source exports assimilate; sink imports/uses/stores it.",trap:"Direction depends on source-sink relationship."}],
      [{title:"Predict osmosis",steps:["Compare water potentials on both sides of a selectively permeable membrane.","Water moves from the higher-potential side toward lower potential under the stated equilibrium model.","Check whether solute can cross; if it can, the simple prediction may change.","Describe the cell response with the correct direction of water flow." ]},{title:"Explain xylem ascent",steps:["Water evaporates from moist mesophyll surfaces through stomata.","Evaporation increases tension in leaf xylem.","Cohesion transmits tension down a continuous water column.","Root uptake replaces water lost; describe the mechanism as a system rather than one isolated force." ]}],
      ["Treating transpiration and translocation as the same process.","Saying xylem transport is driven only by root pressure.","Forgetting the Casparian strip's role.","Assuming phloem always carries material downward."],
      ["NEET focus: water potential, apoplast/symplast, stomata and source-sink flow."],
      ["What property does the Casparian strip regulate?","Why does transpiration create xylem tension?","How can source/sink status change?"],
      ["Apoplast: cell-wall/extracellular pathway.","Symplast: connected cytoplasm pathway.","Translocation: movement of assimilates in phloem."]),
    make("Class 11","Mineral Nutrition",
      "Distinguish essential mineral elements, macro/micronutrients, deficiency symptoms, nitrogen fixation and assimilation.",
      [
        ["Essentiality and criteria","An element is essential if a plant cannot complete its life cycle without it, its role cannot be replaced by another element, and it is directly involved in metabolism/structure. Essentiality depends on function, not the absolute amount needed. Macronutrients are needed in relatively large quantities; micronutrients are needed in smaller quantities but remain essential."],
        ["Roles and deficiency","Elements contribute to proteins, nucleic acids, chlorophyll, membranes, enzyme cofactors and osmotic balance. Deficiency symptoms depend on function and mobility: mobile elements may show symptoms first in older leaves as the plant reallocates them; less-mobile elements often affect young tissues first. Chlorosis is yellowing, necrosis is tissue death, and stunted growth is non-specific."],
        ["Nitrogen cycle and biological fixation","Atmospheric N₂ is not directly usable by most plants. Nitrogen fixation converts N₂ into reduced nitrogen forms by specialised microbes or industrial processes; nitrification, assimilation, ammonification and denitrification transform nitrogen through ecosystems. Legume root nodules house nitrogen-fixing bacteria in a controlled symbiosis."],
        ["Hydroponics and diagnosis","Hydroponics grows plants in nutrient solutions and can identify element requirements by omission experiments. If excluding an element causes a reproducible deficiency and restoring it reverses symptoms, the evidence supports its importance. Diagnose carefully because several deficiencies can cause similar symptoms and root damage may mimic nutrient limitation."]
      ],
      [{label:"Macronutrient vs micronutrient",meaning:"Classified by amount required, not biological importance.",trap:"Micronutrients are still essential."},{label:"Chlorosis",meaning:"Yellowing commonly associated with reduced chlorophyll.",trap:"It can have several causes; do not assign one mineral without clues."}],
      [{title:"Interpret an omission experiment",steps:["Compare a complete nutrient solution with a treatment missing one element.","Record growth and symptom location, considering element mobility.","Restore the omitted element to test recovery.","Use controls to rule out pH, water or other nutrient differences." ]},{title:"Track nitrogen transformations",steps:["Fixation converts atmospheric N₂ to reduced nitrogen compounds.","Nitrification converts ammonium toward nitrite/nitrate.","Plants assimilate inorganic nitrogen into organic molecules.","Decomposition returns nitrogen; denitrification can return N₂ to the atmosphere." ]}],
      ["Calling micronutrients unimportant.","Assuming every yellow leaf indicates the same deficiency.","Confusing nitrogen fixation with nitrification.","Ignoring plant age and nutrient mobility in symptom interpretation."],
      ["NEET focus: essentiality criteria, element roles, deficiency patterns and nitrogen-cycle steps."],
      ["Why can mobile elements show symptoms in older leaves?","What role do root-nodule bacteria play?","How can hydroponics test essentiality?"],
      ["Chlorosis: yellowing from reduced chlorophyll.","Hydroponics: plant cultivation in nutrient solution.","Nitrogen fixation: conversion of atmospheric N₂ to biologically usable reduced forms."]),
    make("Class 11","Photosynthesis in Higher Plants",
      "Connect light absorption, electron transport, ATP/NADPH formation, carbon fixation and the adaptations of C₃/C₄ plants.",
      [
        ["Chloroplast and pigments","Chloroplast thylakoid membranes contain photosystems and electron-transport components; stroma contains enzymes of carbon fixation. Chlorophylls absorb useful wavelengths, while accessory pigments broaden light capture and protect the photosynthetic apparatus. Absorbed light energy drives electron transfer rather than directly turning CO₂ into sugar in one step."],
        ["Light-dependent reactions","Water oxidation supplies electrons and releases O₂ in oxygenic photosynthesis. Electron transport builds a proton gradient that powers ATP synthase; reducing equivalents form NADPH. Cyclic electron flow around photosystem I produces ATP without net NADPH or oxygen evolution in the simplified model. Keep ATP generation, reducing power and oxygen evolution distinct."],
        ["Calvin cycle and photorespiration","Rubisco fixes CO₂ to RuBP in the Calvin cycle; reduction stages use ATP and NADPH to form carbohydrate intermediates, and RuBP is regenerated. In C₃ plants, the first stable product has three carbons. Rubisco can also react with O₂, causing photorespiration and loss of efficiency in suitable conditions."],
        ["C₄ adaptation and limiting factors","C₄ plants initially fix CO₂ into a four-carbon compound in mesophyll cells and concentrate CO₂ around Rubisco in bundle-sheath cells. This can reduce photorespiration in hot/high-light environments but uses additional ATP. Light, CO₂, temperature, water and leaf condition affect rates; a limiting factor is the one currently restricting the process."]
      ],
      [{label:"Overall summary",meaning:"6CO₂ + 6H₂O → carbohydrate + 6O₂ under light (simplified net equation).",trap:"Released oxygen originates from water, not carbon dioxide."},{label:"C₃ vs C₄",meaning:"C₃ uses the Calvin cycle's initial 3-carbon product; C₄ adds a CO₂-concentrating step with a 4-carbon product.",trap:"C₄ does not mean the Calvin cycle disappears."},{label:"Photophosphorylation",meaning:"ATP synthesis driven by light-generated electron transport/proton gradient.",trap:"Cyclic and non-cyclic routes differ in products."}],
      [{title:"Trace the source of oxygen",steps:["Light excites the photosynthetic electron-transfer system.","Water is oxidised to replace electrons and releases protons and O₂.","Electrons pass through transport components and support ATP/NADPH production.","CO₂ carbon is incorporated into organic intermediates separately." ]},{title:"Compare C₃ and C₄",steps:["C₃ plants directly use Rubisco for initial CO₂ fixation in mesophyll chloroplasts.","C₄ plants first fix bicarbonate/CO₂ into a four-carbon compound.","The compound delivers concentrated CO₂ to bundle-sheath Rubisco.","This reduces photorespiration under appropriate conditions but costs additional ATP." ]}],
      ["Saying O₂ comes from CO₂.","Treating light reactions and Calvin cycle as the same location/process.","Claiming C₄ plants never use the Calvin cycle.","Confusing cyclic electron flow with oxygen-releasing linear flow."],
      ["NEET focus: photosystem roles, products of light reactions, C₃/C₄ comparison and photorespiration."],
      ["What supplies electrons for oxygenic photosynthesis?","Where does the Calvin cycle occur?","Why can C₄ plants be more efficient in hot conditions?"],
      ["Photolysis: light-driven splitting of water.","Rubisco: enzyme catalysing CO₂ fixation and oxygenation reactions.","Photorespiration: pathway associated with Rubisco oxygenation."]),
    make("Class 11","Respiration in Plants",
      "Follow glucose breakdown through glycolysis, pyruvate oxidation, Krebs cycle and electron transport; compare aerobic and anaerobic pathways.",
      [
        ["Glycolysis","Glycolysis occurs in the cytosol and converts one glucose molecule into two pyruvate molecules, with a net gain of ATP and NADH in the standard accounting. It does not directly require oxygen. ATP is made through substrate-level phosphorylation at particular steps; distinguish gross ATP produced from net ATP after the investment phase."],
        ["Aerobic oxidation and Krebs cycle","Under aerobic conditions, pyruvate is processed to acetyl-CoA and enters the mitochondrial matrix pathway. The Krebs/citric-acid cycle releases CO₂ and produces reduced electron carriers, ATP/GTP-equivalent and intermediates for biosynthesis. In eukaryotes, the inner mitochondrial membrane houses the electron-transport chain and ATP synthase."],
        ["Oxidative phosphorylation","Electrons from NADH/FADH₂ pass through transport complexes; energy pumps protons across the inner membrane. ATP synthase allows protons to return down the electrochemical gradient and couples it to ATP formation. Oxygen is the terminal electron acceptor in aerobic respiration and is reduced to water. Oxygen is not directly consumed by glycolysis itself."],
        ["Fermentation and respiratory quotient","Without aerobic electron transport, fermentation regenerates NAD⁺ so glycolysis can continue, but ATP yield is much smaller. Alcoholic and lactic pathways have different end products. Respiratory quotient is CO₂ released divided by O₂ consumed over the measured interval; its value varies with substrate and pathway, so do not assume it is always exactly one."]
      ],
      [{label:"Glycolysis location",meaning:"Cytosol; glucose → two pyruvate with net ATP and NADH.",trap:"Glycolysis does not directly need oxygen."},{label:"Oxidative phosphorylation",meaning:"Proton gradient at inner mitochondrial membrane drives ATP synthase.",trap:"Oxygen is terminal electron acceptor in aerobic respiration."},{label:"RQ",meaning:"Volume of CO₂ evolved / volume of O₂ consumed.",trap:"The value depends on respiratory substrate."}],
      [{title:"Trace energy flow",steps:["Glycolysis makes pyruvate, ATP and NADH in the cytosol.","In aerobic conditions, pyruvate-derived acetyl-CoA enters the Krebs cycle.","Reduced carriers donate electrons to the inner-membrane electron transport chain.","The proton gradient drives ATP synthase; oxygen accepts electrons at the end." ]},{title:"Explain fermentation",steps:["When electron transport cannot oxidise NADH sufficiently, NAD⁺ must be regenerated.","Fermentation transfers electrons to an organic molecule such as pyruvate or a derivative.","Glycolysis can continue making a small net amount of ATP.","The ATP yield is far smaller than full aerobic oxidation of glucose." ]}],
      ["Claiming fermentation produces the same ATP as aerobic respiration.","Confusing glycolysis and Krebs-cycle locations.","Saying oxygen is the direct reactant in glycolysis.","Treating RQ as universally fixed."],
      ["NEET focus: location and products of pathways, ATP accounting, electron transport and fermentation."],
      ["Where does glycolysis occur?","What drives ATP synthase?","Why must NAD⁺ be regenerated during fermentation?"],
      ["Substrate-level phosphorylation: ATP formation directly linked to a chemical reaction.","Oxidative phosphorylation: ATP synthesis coupled to electron transport.","Respiratory quotient: CO₂ produced divided by O₂ consumed."]),
    make("Class 11","Plant Growth and Development",
      "Explain meristems, growth measurements, dormancy, photoperiodism, vernalisation and hormone-controlled responses.",
      [
        ["Growth and differentiation","Growth is a largely irreversible increase in size/mass resulting from cell division, enlargement and associated changes. Meristems contain actively dividing cells. Differentiation gives cells specialised structures/functions; dedifferentiation and redifferentiation are possible in some plant tissues. Growth rate may be arithmetic or geometric depending on the observed pattern and assumptions."],
        ["Plant growth regulators","Auxins influence elongation, tropic responses and apical dominance; gibberellins affect stem elongation and seed germination; cytokinins promote cell division and can delay senescence in suitable conditions; abscisic acid participates in stress responses and dormancy; ethylene affects ripening and other responses. Effects depend on organ, concentration and interactions."],
        ["Photoperiodism and vernalisation","Photoperiodism is a flowering response to day/night duration; plants may be short-day, long-day or day-neutral under the stated conditions. The uninterrupted dark period may be crucial for some responses. Vernalisation is promotion of flowering by exposure to low temperature in appropriate plants. Neither response should be explained simply as 'more sunlight means more flowering'."],
        ["Tropisms, dormancy and senescence","Phototropism responds to light direction; gravitropism responds to gravity; other tropisms respond to water or touch. Dormancy pauses growth until favourable conditions or cues occur. Senescence involves coordinated ageing processes. Separate a directional growth response from general growth rate and from seasonal developmental timing."]
      ],
      [{label:"Auxin",meaning:"Associated with cell elongation, tropism and apical dominance in textbook examples.",trap:"The response depends on tissue and concentration."},{label:"ABA",meaning:"Stress-related responses and seed dormancy; often linked to stomatal closure.",trap:"Plant hormones interact; avoid one-function-only absolutism."},{label:"Photoperiodism",meaning:"Developmental response to day/night length.",trap:"Dark-period length can be critical."}],
      [{title:"Predict a photoperiod response",steps:["Classify the plant as short-day, long-day or day-neutral from the prompt.","Identify the critical photoperiod/darkness condition.","Determine whether the treatment meets that condition.","Avoid relying on total daily sunlight alone if night interruption is specified." ]},{title:"Match a regulator",steps:["Identify the response described: ripening, elongation, division, stress or dormancy.","Choose the regulator commonly associated with that response in the syllabus.","State the effect and the context.","Acknowledge that responses depend on concentration and tissue." ]}],
      ["Treating every hormone as having only one role.","Confusing photoperiodism with photosynthesis rate.","Ignoring dark-period interruption.","Assuming growth is always linear."],
      ["NEET focus: regulator-role matches, photoperiod groups, growth curves and dormancy cues."],
      ["How do photoperiodism and vernalisation differ?","Which regulator is linked to fruit ripening?","What is apical dominance?"],
      ["Meristem: actively dividing plant tissue.","Tropism: directional growth response to a stimulus.","Vernalisation: flowering promotion by low-temperature treatment."]),
    make("Class 11","Breathing and Exchange of Gases",
      "Trace ventilation, alveolar diffusion, gas carriage in blood, oxygen dissociation and regulation of breathing.",
      [
        ["Ventilation mechanics","Inspiration normally occurs when diaphragm/intercostal action increases thoracic volume, lowering intrapulmonary pressure relative to atmosphere. Expiration at rest is largely passive as elastic structures recoil. Pressure, volume and airflow direction must be described relative to the same reference; larger thoracic volume generally lowers pressure in the idealised model."],
        ["Alveolar exchange","Alveoli have large surface area, thin moist walls and rich capillary networks. O₂ diffuses from alveolar air into blood down a partial-pressure gradient; CO₂ diffuses in the opposite direction under normal conditions. Exchange depends on gradients, surface area, thickness and ventilation/perfusion matching."],
        ["Transport of oxygen and carbon dioxide","Most oxygen travels reversibly bound to haemoglobin; a smaller amount is dissolved in plasma. The oxygen-haemoglobin dissociation curve responds to pH, CO₂, temperature and other factors, aiding loading in lungs and unloading in tissues. CO₂ is transported dissolved, bound to proteins and chiefly as bicarbonate in the standard human physiology account."],
        ["Control and respiratory volumes","Respiratory centres respond to chemical and neural signals; changes in CO₂/H⁺ are important drivers under typical conditions. Tidal volume is air moved in a normal breath; vital capacity combines inspiratory reserve, tidal volume and expiratory reserve. Distinguish lung capacity from rate and from actual gas exchange."]
      ],
      [{label:"Gas exchange",meaning:"Diffusion down partial-pressure gradients.",trap:"Do not describe it as active transport under ordinary alveolar conditions."},{label:"Oxygen transport",meaning:"Most O₂ is carried reversibly by haemoglobin.",trap:"Oxygen affinity changes with pH, CO₂ and temperature."},{label:"CO₂ transport",meaning:"A large fraction travels as bicarbonate after conversion in blood.",trap:"CO₂ uses more than one transport form."}],
      [{title:"Follow one oxygen molecule",steps:["Ventilation brings air to an alveolus.","O₂ diffuses into pulmonary capillary blood and binds haemoglobin.","Circulation delivers blood to tissues with lower O₂ partial pressure.","O₂ unloads and diffuses into cells." ]},{title:"Calculate vital capacity",steps:["Use VC=IRV+TV+ERV.","Insert the supplied inspiratory reserve, tidal volume and expiratory reserve.","Keep all volumes in the same unit.","Do not add residual volume unless calculating total lung capacity." ]}],
      ["Confusing ventilation with cellular respiration.","Saying all O₂ is dissolved directly in plasma.","Forgetting partial-pressure gradients.","Including residual volume in vital capacity."],
      ["NEET focus: breathing mechanics, gas transport, curve shifts and lung-volume definitions."],
      ["Why do alveoli allow efficient diffusion?","How is most oxygen transported?","Which volumes add to vital capacity?"],
      ["Ventilation: bulk movement of air.","Partial pressure: contribution of one gas to total pressure.","Vital capacity: maximum air exhaled after maximal inspiration."]),
    make("Class 11","Body Fluids and Circulation",
      "Connect blood components, blood groups, clotting, heart chambers, conduction, cardiac cycle and circulation pathways.",
      [
        ["Blood and lymph","Plasma carries dissolved substances; erythrocytes carry haemoglobin, leucocytes support defence and platelets participate in clotting. Lymph returns interstitial fluid to circulation and transports some absorbed lipids. Blood is connective tissue because cells are suspended in extracellular plasma."],
        ["ABO/Rh compatibility concepts","ABO blood groups depend on antigens on red cells and corresponding antibodies in plasma under the standard model. A mismatched transfusion can cause antibody-mediated agglutination/haemolysis. Rh status matters especially in pregnancy and transfusion contexts. Clinical transfusion compatibility is more complex than a simple donor chart; exam problems use the stated model."],
        ["Heart and double circulation","The right side pumps deoxygenated blood to pulmonary circulation; the left side pumps oxygenated blood to systemic circulation. Valves limit backflow. Atria receive blood, ventricles eject it. Double circulation separates pulmonary and systemic paths and supports pressure/flow differences."],
        ["Cardiac cycle and regulation","Electrical excitation begins at the sinoatrial node in the typical description, spreads through atria, pauses at AV node and travels through ventricular conducting tissue. A cardiac cycle includes atrial systole, ventricular systole and joint diastole. Arterial pressure depends on cardiac output and vascular resistance; pulse is the pressure wave associated with ventricular ejection."]
      ],
      [{label:"Cardiac conduction",meaning:"SA node → AV node → bundle/branches/Purkinje system in the common sequence.",trap:"The conduction system coordinates contraction; valves do not generate the electrical signal."},{label:"Double circulation",meaning:"Pulmonary circulation and systemic circulation in series.",trap:"Right heart pumps to lungs; left heart pumps to body."}],
      [{title:"Trace blood flow",steps:["Body → venae cavae → right atrium → right ventricle.","Right ventricle → pulmonary artery → lungs → pulmonary veins.","Pulmonary veins → left atrium → left ventricle → aorta.","A vein is named by flow toward the heart, not by oxygen content." ]},{title:"Classify blood cells",steps:["Erythrocytes specialise in oxygen carriage.","Leucocytes support immune defence and have several subtypes.","Platelets contribute to haemostasis/clot formation.","Plasma carries water, ions, nutrients, hormones and waste." ]}],
      ["Saying all arteries carry oxygenated blood (pulmonary artery is the common exception).","Confusing valves with conduction nodes.","Describing ABO group by plasma antibodies only and ignoring antigens.","Calling lymph a form of red blood cell."],
      ["NEET focus: blood-cell roles, flow sequence, heart valves, cardiac conduction and pulse/BP basics."],
      ["Why are pulmonary artery and vein exceptions to the usual oxygen rule?","Which node initiates the normal heartbeat?","What is the role of platelets?"],
      ["Erythrocyte: red blood cell.","Haemostasis: processes stopping bleeding.","Systole: contraction phase of a heart chamber."]),
    make("Class 11","Excretory Products and their Elimination",
      "Explain nitrogenous waste, nephron filtration/reabsorption/secretion, urine concentration and hormonal regulation.",
      [
        ["Types of nitrogenous waste","Ammonia is toxic but requires much water for excretion; urea is less toxic and common in mammals; uric acid conserves water and is typical of many birds/reptiles/insects. Excretion removes metabolic waste; egestion eliminates undigested food. Do not confuse the two processes."],
        ["Nephron structure","Glomerulus filters plasma into Bowman's capsule under pressure. The tubule modifies filtrate through selective reabsorption and secretion. Proximal tubule reabsorbs a large fraction of water/solutes; the loop of Henle establishes a concentration gradient; distal segments and collecting ducts fine-tune composition. Filtrate is not yet final urine."],
        ["Countercurrent and concentration","Opposing fluid flow in loop/medullary vessels helps establish and preserve osmotic gradients in the renal medulla. Water permeability of collecting ducts is regulated in part by antidiuretic hormone. Concentrating urine requires both a gradient and selective permeability; hormonal action alone does not create the entire gradient."],
        ["Hormonal feedback and clearance","ADH increases collecting-duct water reabsorption; aldosterone supports Na⁺ reabsorption and K⁺ secretion in relevant nephron segments. The renin-angiotensin system and atrial natriuretic factors contribute to volume/pressure regulation. Homeostasis is dynamic; the kidney adjusts water, ions and acid-base balance as conditions change."]
      ],
      [{label:"Nephron sequence",meaning:"Glomerulus/Bowman's capsule → proximal tubule → loop of Henle → distal tubule → collecting duct.",trap:"The collecting duct receives fluid from multiple nephrons."},{label:"ADH",meaning:"Raises collecting-duct water permeability and supports water conservation.",trap:"ADH is not the only factor controlling urine concentration."}],
      [{title:"Trace filtrate",steps:["Glomerular filtration forms initial filtrate.","Selective reabsorption returns useful solutes/water to blood.","Tubular secretion moves selected substances into filtrate.","Collecting-duct water regulation and the medullary gradient affect final urine concentration." ]},{title:"Compare waste strategies",steps:["Identify habitat and water availability in the question.","Ammonia requires abundant water for dilution.","Urea trades toxicity and water conservation.","Uric acid conserves water but requires metabolic energy to produce." ]}],
      ["Equating filtrate with final urine.","Saying every filtered substance is excreted.","Confusing ADH and aldosterone roles.","Calling undigested food excretion rather than egestion."],
      ["NEET focus: nephron segment functions, waste products and hormone effects."],
      ["Where does glomerular filtration occur?","How does ADH influence urine?","Why do different animals use different nitrogenous wastes?"],
      ["Filtrate: fluid entering renal tubules after filtration.","Reabsorption: return of selected filtrate components to blood.","Tubular secretion: transfer of selected substances into tubule."]),
    make("Class 11","Locomotion and Movement",
      "Link skeletal structure, joints, muscle contraction, sarcomeres and neural control to movement and posture.",
      [
        ["Skeleton and joints","The skeleton protects organs, supports body shape and provides levers for muscles. Joints differ in movement range and structure. Synovial joints have a cavity and lubricating fluid; fibrous/cartilaginous joints allow less movement in the standard comparison. Tendons attach muscle to bone and ligaments connect bones."],
        ["Sarcomere organisation","Skeletal muscle fibres contain myofibrils made of sarcomeres. Thin actin and thick myosin filaments interact during contraction. The Z lines move closer as overlap changes; filaments slide rather than shortening themselves. ATP and Ca²⁺ regulate cross-bridge cycling; the exact mechanism should be described in the correct order."],
        ["Sliding-filament mechanism","A motor signal leads to Ca²⁺ release from sarcoplasmic reticulum. Ca²⁺ binds regulatory proteins, allowing myosin heads to interact with actin. ATP binding detaches myosin, hydrolysis re-cocks the head, and power strokes move actin relative to myosin. ATP is also needed for calcium reuptake, so lack of ATP prevents normal relaxation."],
        ["Movement disorders and energy","Muscle work uses ATP supplied by cellular metabolism; short intense exertion and prolonged activity recruit energy pathways differently. Myasthenia gravis, muscular dystrophy, arthritis and osteoporosis affect different structures/processes, so do not group all as muscle diseases. Connect symptoms to neuromuscular junction, muscle tissue, joints or bone as appropriate."]
      ],
      [{label:"Sarcomere",meaning:"Contractile unit between adjacent Z lines.",trap:"During contraction, filament length stays essentially constant while overlap changes."},{label:"Ca²⁺ and ATP",meaning:"Calcium exposes binding sites; ATP powers cross-bridge cycling and detachment.",trap:"ATP is required for relaxation processes too."}],
      [{title:"Order muscle contraction",steps:["Motor impulse triggers acetylcholine release at neuromuscular junction.","Signal leads to calcium release from sarcoplasmic reticulum.","Calcium exposes actin binding sites; myosin cross-bridges cycle using ATP.","Calcium is pumped back and regulatory proteins block interaction during relaxation." ]},{title:"Classify a movement problem",steps:["Determine whether the prompt describes bone, joint, muscle or nerve/junction.","Identify the structure and its normal role.","Connect altered structure/function to the stated symptom.","Avoid diagnosing a different system just because movement is affected." ]}],
      ["Saying filaments themselves shrink during contraction.","Forgetting calcium's regulatory role.","Saying ATP only initiates contraction and is unnecessary for relaxation.","Confusing tendons with ligaments."],
      ["NEET focus: sarcomere bands, cross-bridge sequence, skeletal/joint roles and disorder distinctions."],
      ["What changes during sliding-filament contraction?","Why is ATP needed for relaxation?","How are tendons and ligaments different?"],
      ["Sarcomere: repeating contractile unit of striated muscle.","Myofibril: chain of contractile units in a muscle fibre.","Neuromuscular junction: motor-neuron/muscle communication site."]),
    make("Class 11","Neural Control and Coordination",
      "Explain resting/action potentials, synapses, CNS/PNS organisation, reflex arcs and sensory transduction.",
      [
        ["Neuron and resting potential","Dendrites receive signals, soma integrates them and the axon conducts impulses. Ion gradients and selective membrane permeability produce a resting membrane potential. The Na⁺/K⁺ pump maintains gradients over time, while voltage-gated channels mediate rapid action potentials. A neuron is excitable because membrane voltage changes trigger controlled ion movement."],
        ["Action potential","Depolarisation begins when threshold opens voltage-gated Na⁺ channels; Na⁺ influx makes the membrane potential more positive. Na⁺ channels inactivate and K⁺ channels contribute to repolarisation; a refractory period limits immediate re-firing. In myelinated axons, conduction is faster because action potentials are regenerated at nodes of Ranvier."],
        ["Synaptic transmission and reflex","Chemical synapses release neurotransmitter from a presynaptic terminal; it crosses the cleft and binds receptors on the postsynaptic cell. A reflex arc may involve receptor, sensory neuron, interneuron, motor neuron and effector, creating a rapid stereotyped response. Not every reflex requires conscious cortical processing before the response begins."],
        ["CNS and sensory organs","The brain and spinal cord form the CNS; cranial/spinal nerves and ganglia form parts of the PNS. Sensory receptors convert environmental energy into signals. Vision, hearing, balance, smell and taste each use specialised transduction mechanisms; compare structure and function rather than memorising isolated labels."]
      ],
      [{label:"Action potential",meaning:"Rapid voltage change created by ion-channel opening/inactivation.",trap:"The Na⁺/K⁺ pump maintains gradients but does not directly make each action-potential spike."},{label:"Chemical synapse",meaning:"Neurotransmitter-mediated signal transfer across a synaptic cleft.",trap:"Direction is typically presynaptic to postsynaptic."}],
      [{title:"Trace a reflex",steps:["A receptor detects a stimulus.","Sensory neuron brings input to spinal/CNS circuitry.","The circuit activates a motor neuron.","The effector produces a response; later brain processing can inform awareness." ]},{title:"Compare myelinated conduction",steps:["Myelin insulates internodal membrane regions.","Action potentials regenerate at nodes of Ranvier.","Impulse appears to jump between nodes (saltatory conduction).","This is generally faster than continuous propagation along an unmyelinated axon." ]}],
      ["Confusing resting potential with an action potential.","Saying the sodium-potassium pump causes the rapid Na⁺ influx spike directly.","Treating every response as requiring conscious brain involvement first.","Mixing CNS and PNS components."],
      ["NEET focus: neuron structure, ion sequence, synapse, reflex arc and sensory-receptor functions."],
      ["What causes depolarisation in a typical neuronal action potential?","What is a synaptic cleft?","Why does myelin increase conduction speed?"],
      ["Depolarisation: membrane potential becomes less negative/more positive.","Refractory period: interval limiting immediate re-excitation.","Transduction: conversion of stimulus energy into a biological signal."]),
    make("Class 11","Chemical Coordination and Integration",
      "Organise endocrine glands, hormone effects and feedback loops; distinguish peptide, steroid and amine hormone mechanisms.",
      [
        ["Endocrine signalling","Endocrine glands release hormones into blood; hormones act on target cells with appropriate receptors. Hormone concentration, receptor expression, feedback and clearance shape response. A hormone does not affect every cell identically just because blood carries it throughout the body."],
        ["Hypothalamus and pituitary","The hypothalamus integrates neural and endocrine inputs and controls pituitary function through releasing/inhibiting hormones and neural connections. The anterior pituitary releases multiple trophic hormones; the posterior pituitary releases oxytocin and ADH made in hypothalamic neurons. Distinguish where a hormone is synthesised from where it is released."],
        ["Major endocrine functions","Thyroid hormones affect metabolic activity and development; insulin lowers circulating blood glucose through uptake/storage pathways and glucagon raises it through opposing pathways; adrenal hormones participate in stress, salt/water balance and metabolism; parathyroid hormone supports calcium regulation. Reproductive hormones coordinate gamete production and reproductive cycles."],
        ["Feedback and disorder logic","Negative feedback reduces deviation from a regulated variable and is common in endocrine axes. A hormone excess/deficiency can arise from gland, target-tissue, receptor or feedback problems. Explain the mechanism before naming a disorder; the same symptom can have multiple causes."]
      ],
      [{label:"Negative feedback",meaning:"Response counteracts a deviation in the regulated variable.",trap:"Positive feedback exists but is not the default for routine homeostasis."},{label:"ADH",meaning:"Supports water conservation by increasing collecting-duct water permeability.",trap:"Produced in hypothalamic neurons and released from posterior pituitary."},{label:"Insulin/glucagon",meaning:"Coordinate glucose storage/use vs mobilisation under changing blood glucose.",trap:"Hormone effects are coordinated, not isolated switches."}],
      [{title:"Trace glucose regulation",steps:["After a meal, blood glucose rises.","Pancreatic beta cells release insulin.","Uptake and storage processes help reduce glucose toward the regulated range.","Lower glucose reduces the stimulus; describe this as negative feedback." ]},{title:"Classify hormone action",steps:["Determine whether the receptor is on the membrane or intracellular in the given model.","Peptide hormones commonly signal through membrane receptors; steroid hormones often act through intracellular receptors.","Link receptor type to signal pathway and response timing where the syllabus expects it.","Do not assume every hormone in one chemical family has identical kinetics." ]}],
      ["Saying hormones affect all tissues equally.","Confusing synthesis site and release site for posterior pituitary hormones.","Treating negative feedback as a process that amplifies deviation.","Mixing insulin and glucagon roles."],
      ["NEET focus: gland-hormone-function, feedback, receptor mechanisms and hyper/hyposecretion logic."],
      ["Why is a hormone effect target-specific?","Where are ADH and oxytocin synthesised?","How does negative feedback stabilise glucose?"],
      ["Endocrine gland: releases signalling molecules into circulation.","Target cell: cell possessing appropriate receptor machinery.","Trophic hormone: hormone that regulates another endocrine gland."]),
    make("Class 12","Sexual Reproduction in Flowering Plants",
      "Trace flower structures, micro/megaspore formation, pollination, double fertilisation and development of seeds/fruits.",
      [
        ["Male and female gametophytes","Anther microspore mother cells undergo meiosis to form haploid microspores that develop into pollen grains. In the ovule, the megaspore mother cell undergoes meiosis; typically one functional megaspore develops into the embryo sac in the standard textbook model. Keep sporogenesis (spore formation) separate from fertilisation."],
        ["Pollination and compatibility","Pollination transfers pollen to a receptive stigma. Agents include wind, water and animals; floral traits can reflect these adaptations. Self-incompatibility, dichogamy, herkogamy and other outbreeding devices reduce selfing under relevant conditions. A pollen grain landing on a stigma has not yet fused with the egg."],
        ["Pollen-tube growth and double fertilisation","A compatible pollen grain germinates; the tube grows through stigma/style and carries male gametes to the ovule. One male gamete fuses with the egg to form the zygote (syngamy). The other fuses with the central cell nuclei in the typical embryo sac, producing the primary endosperm nucleus (triple fusion). These two events form double fertilisation."],
        ["Post-fertilisation development","The zygote develops into the embryo; endosperm supports the developing embryo; ovule becomes seed and ovary commonly becomes fruit. Integuments form the seed coat. Seed structure and storage can vary among species. Fruit/seed dispersal and dormancy support survival and spread, but these outcomes depend on species and environment."]
      ],
      [{label:"Double fertilisation",meaning:"Syngamy forms the zygote; triple fusion forms the primary endosperm nucleus.",trap:"The two products are distinct."},{label:"Ovule/ovary",meaning:"Ovule develops into seed; ovary generally develops into fruit.",trap:"Do not swap the terms."}],
      [{title:"Order the process",steps:["Microsporogenesis and megasporogenesis produce haploid spores.","Pollen matures and pollination delivers it to stigma.","Compatible pollen tube delivers male gametes to the embryo sac.","Syngamy and triple fusion occur, followed by embryo/endosperm and seed/fruit development." ]},{title:"Distinguish events",steps:["Pollination is transfer of pollen to stigma.","Germination and tube growth follow compatible pollination.","Fertilisation is fusion of gametes/nuclei in the ovule.","Seed formation is post-fertilisation development; it is not synonymous with pollination." ]}],
      ["Confusing pollination with fertilisation.","Saying both male gametes form the zygote.","Swapping ovule and ovary outcomes.","Calling triple fusion syngamy."],
      ["NEET focus: embryo-sac structures, pollen-tube pathway, outbreeding devices and double-fertilisation terms."],
      ["What is the difference between syngamy and triple fusion?","Which structure becomes the seed?","What do outbreeding devices reduce?"],
      ["Microsporogenesis: formation of microspores through meiosis.","Pollination: transfer of pollen to stigma.","Endosperm: tissue supporting embryo development."]),
    make("Class 12","Human Reproduction",
      "Connect male/female reproductive anatomy to gametogenesis, reproductive cycles, fertilisation, implantation and placental support.",
      [
        ["Male reproductive system and spermatogenesis","Testes contain seminiferous tubules where spermatogenesis occurs; Sertoli cells support developing germ cells and Leydig cells produce androgens. Spermatogenesis proceeds through mitotic, meiotic and differentiation stages. Sperm travel through ducts and acquire motility/function during maturation. Gamete ploidy is reduced by meiosis."],
        ["Female reproductive system and oogenesis","Ovaries produce oocytes and hormones; oogenesis begins before birth and contains meiotic arrest stages. Typically one functional ovum results from primary oocyte division because cytoplasm is unevenly distributed among products. Oviducts support fertilisation and transport; the uterus supports implantation and pregnancy."],
        ["Menstrual cycle and hormonal control","GnRH, FSH, LH, oestrogens and progesterone interact through feedback. Follicular development precedes ovulation; corpus-luteum hormones influence the uterine lining. The sequence depends on coordinated hormone changes rather than one hormone acting alone. Avoid confusing ovulation (release of oocyte) with fertilisation or implantation."],
        ["Fertilisation, implantation and pregnancy","Fertilisation usually occurs in the oviduct; cleavage forms an early embryo that becomes a blastocyst and implants in the uterine lining. Placental tissues exchange gases, nutrients and wastes while maternal and fetal blood normally remain in separate circulations. Hormones help maintain pregnancy; parturition and lactation have additional endocrine control."]
      ],
      [{label:"Spermatogenesis",meaning:"Meiosis and differentiation form haploid sperm from germ cells.",trap:"Sperm production and sperm maturation are distinct processes."},{label:"Oogenesis",meaning:"Formation of a female gamete with unequal cytoplasmic division.",trap:"Meiotic arrest and timing differ from spermatogenesis."},{label:"Fertilisation site",meaning:"Usually the oviduct in humans.",trap:"Fertilisation is not implantation."}],
      [{title:"Follow hormone events",steps:["FSH supports follicular development; follicles release oestrogens.","The LH surge triggers ovulation in the typical cycle.","The corpus luteum secretes progesterone and other hormones after ovulation.","If pregnancy does not occur, hormone support changes and the uterine lining is shed." ]},{title:"Order early development",steps:["Fertilisation produces a zygote.","Cleavage divisions generate a multicellular early embryo.","Blastocyst stage precedes implantation into the uterine lining.","Placental development supports exchange later in pregnancy." ]}],
      ["Confusing meiosis stages with gamete maturation.","Saying fertilisation happens in the uterus as the usual site.","Mixing ovulation, fertilisation and implantation.","Claiming maternal and fetal blood directly mix normally in the placenta."],
      ["NEET focus: anatomy/hormones, menstrual-cycle sequence, gamete ploidy and embryo development stages."],
      ["Where does fertilisation usually occur?","What event is triggered by the LH surge?","What is the role of the placenta?"],
      ["Gametogenesis: production of gametes.","Ovulation: release of an oocyte from an ovarian follicle.","Implantation: attachment/embedding of blastocyst into uterine lining."]),
    make("Class 12","Reproductive Health",
      "Compare contraception, assisted reproductive technologies, infertility causes and prevention of sexually transmitted infections.",
      [
        ["Scope of reproductive health","Reproductive health includes physical, emotional and social well-being in reproductive matters, informed choices, access to services, prevention and treatment of conditions. Education and services must be evidence-based and respectful. Separate population-level public-health concepts from an individual's medical diagnosis."],
        ["Contraception mechanisms","Barrier methods reduce sperm entry and some also reduce STI transmission. Hormonal methods alter ovulation/mucus/endometrium depending on formulation; intrauterine devices act within the uterus; permanent methods block reproductive ducts. Effectiveness depends on method and correct, consistent use. Not all methods protect against infections."],
        ["Infertility and assisted reproductive technology","Infertility can involve male, female, combined or unexplained factors. ART methods such as IVF, embryo transfer, and selected gamete/zygote transfer procedures support particular clinical situations. Method selection depends on diagnosis and clinical guidance; exam-level definitions should not be confused with a promise of success."],
        ["STI prevention and care","STIs differ in pathogen, transmission, symptoms and treatment. Some are bacterial and treatable with appropriate antimicrobials; viral infections may be managed or prevented differently. Condoms reduce risk but do not provide absolute protection against every infection. Screening and prompt qualified care are important because some infections may initially be asymptomatic."]
      ],
      [{label:"Contraceptive classes",meaning:"Barrier, hormonal, intrauterine and permanent approaches have distinct mechanisms.",trap:"Effectiveness and STI protection differ by method."},{label:"Condoms",meaning:"Barrier method that also lowers STI transmission risk.",trap:"Risk reduction is not an absolute guarantee."},{label:"ART",meaning:"Clinical techniques supporting reproduction in selected infertility cases.",trap:"Different procedures address different causes."}],
      [{title:"Choose a method category",steps:["Identify the goal: prevent pregnancy, lower STI risk, or assist conception.","Match the mechanism to the goal.","Check stated constraints, contraindications or clinical context.","Do not claim that every method prevents both pregnancy and infection." ]},{title:"Distinguish ART terms",steps:["IVF involves fertilisation outside the body under clinical conditions.","Embryo/gamete transfer describes subsequent transfer steps.","Other procedures have specific indications and process stages.","Use the exact term and avoid treating ART methods as interchangeable." ]}],
      ["Assuming every contraceptive method prevents STIs.","Equating infertility with a single cause.","Overstating the success of any ART procedure.","Treating STI symptoms as sufficient for self-diagnosis."],
      ["NEET focus: mechanism, protection limits, ART terms and reproductive-health public-health principles."],
      ["Which contraceptive method also reduces STI risk?","Why do different ART procedures address different situations?","Can an STI be asymptomatic?"],
      ["Contraception: methods to reduce likelihood of pregnancy.","STI: infection transmitted through sexual contact/routes.","Infertility: inability to achieve pregnancy after an appropriate period under the relevant clinical definition."]),
    make("Class 12","Principles of Inheritance and Variation",
      "Apply Mendelian segregation, independent assortment, dominance, linkage, sex determination and pedigree reasoning.",
      [
        ["Genes, alleles and Mendel's laws","Alleles are alternative versions of a gene. Segregation separates allele copies into gametes; independent assortment applies to genes whose inheritance meets the model assumptions, including unlinked genes. Dominance describes heterozygote phenotype in a particular trait; it does not mean an allele is more common or better."],
        ["Monohybrid/dihybrid probability","For Aa×Aa under standard Mendelian assumptions, genotype probabilities are 1/4 AA, 1/2 Aa and 1/4 aa; complete dominance yields a 3:1 phenotype expectation. Dihybrid 9:3:3:1 expectations require independent assortment and complete dominance in the typical textbook cross. Ratios are probabilities over many offspring, not guarantees in a small family."],
        ["Extensions and chromosome linkage","Incomplete dominance, codominance, multiple alleles, polygenic inheritance and pleiotropy explain patterns beyond simple dominance. Linked genes tend to be inherited together; crossing over can generate recombinant combinations. Recombination frequency reflects chromosomal distance within the limits of the model, not exact physical distance in all situations."],
        ["Sex determination and pedigrees","Sex-determination systems vary among organisms; the human XX/XY pattern is a common model, not universal across life. Pedigree analysis assigns possible genotypes and tests them against affected/unaffected relatives. Identify whether the trait appears dominant/recessive and autosomal/sex-linked; account for penetrance or missing information if the question introduces them."]
      ],
      [{label:"Segregation",meaning:"Allele copies separate during gamete formation.",trap:"The law applies to alleles at a locus; do not describe it as homologues 'choosing' traits."},{label:"Aa × Aa",meaning:"Expected genotype ratio 1 AA : 2 Aa : 1 aa.",trap:"Phenotype ratio depends on dominance."},{label:"Linkage",meaning:"Genes on the same chromosome can be inherited together.",trap:"Crossing over can still create recombinants."}],
      [{title:"Monohybrid probability",steps:["For Aa×Aa, each parent contributes A or a with probability 1/2.","P(aa)=P(a from first)×P(a from second)=1/4.","P(Aa)=1/2, combining Aa and aA outcomes.","Interpret ratio as expectation, not certainty." ]},{title:"Pedigree strategy",steps:["Mark affected/unaffected individuals and relationships.","Test whether a dominant/recessive model can explain every generation.","Check for father-to-son transmission when considering X-linkage.","Assign genotypes only when supported by evidence; mark uncertain carriers as possible." ]}],
      ["Assuming dominance means commonness.","Treating expected ratios as guaranteed counts.","Applying 9:3:3:1 when genes are linked.","Ignoring genotype uncertainty in pedigrees."],
      ["NEET focus: cross probabilities, pedigree logic, linkage/recombination and inheritance vocabulary."],
      ["What conditions support a 9:3:3:1 ratio?","Can a dominant allele be rare?","What does recombination reveal about linked genes?"],
      ["Allele: gene variant.","Genotype: allele combination.","Phenotype: observable characteristic influenced by genotype/environment."]),
    make("Class 12","Molecular Basis of Inheritance",
      "Trace DNA replication, transcription, RNA processing, translation, genetic code and gene regulation.",
      [
        ["DNA structure and replication","DNA strands are antiparallel and complementary. Semi-conservative replication yields daughter DNA with one parental and one newly synthesised strand. DNA polymerase extends the new strand 5′→3′, requiring a primer. The leading strand is made continuously toward the fork; the lagging strand uses Okazaki fragments joined by ligase."],
        ["Transcription and RNA processing","RNA polymerase uses a DNA template to synthesise RNA. In eukaryotes, primary transcripts may be capped, spliced and polyadenylated before becoming mature mRNA. Introns are removed and exons joined in the common splicing description. Template and coding strands have related sequences but opposite orientation; clearly specify which strand is being written."],
        ["Genetic code and translation","The ribosome reads mRNA codons in a frame; tRNA anticodons pair with codons and deliver amino acids. The genetic code is degenerate, nearly universal in the textbook model, and read in non-overlapping triplets. Start/stop codons have different roles; stop codons do not encode an amino acid."],
        ["Gene regulation and mutation","Gene regulation determines when and how much product is made; regulation can act at transcription, RNA processing, translation and protein activity. A substitution may be silent, missense or nonsense; an insertion/deletion not divisible by three can cause a frameshift. A mutation's consequence depends on context and need not always be harmful."]
      ],
      [{label:"Replication direction",meaning:"DNA polymerase synthesises new DNA 5′→3′.",trap:"Template is read in the opposite direction."},{label:"Central flow",meaning:"DNA → RNA → polypeptide in the basic information-transfer scheme.",trap:"Replication, transcription and translation are separate processes."},{label:"Codon",meaning:"Three-base unit on mRNA specifying an amino acid or stop.",trap:"Read in the correct frame."}],
      [{title:"Trace a gene to protein",steps:["A gene's DNA sequence serves as a template for transcription.","RNA processing in eukaryotes produces mature mRNA.","Ribosomes read codons and tRNAs deliver amino acids.","The polypeptide folds and may be modified before its functional role." ]},{title:"Classify a mutation",steps:["Identify the nucleotide change and coding frame.","Determine whether the codon changes an amino acid or becomes a stop codon if sequence is provided.","Check whether insertion/deletion shifts the frame.","Do not infer phenotype without context about expression and function." ]}],
      ["Reversing 5′/3′ synthesis direction.","Confusing transcription and translation.","Calling all mutations harmful.","Treating a stop codon as specifying an amino acid."],
      ["NEET focus: replication enzymes, strand direction, RNA processing, codons and mutation classes."],
      ["Which enzyme seals Okazaki fragments?","What is removed during RNA splicing?","Why can a frameshift affect downstream amino acids?"],
      ["Okazaki fragment: short DNA segment made discontinuously on lagging strand.","Codon: mRNA triplet specifying amino acid/stop.","Frameshift: change to downstream reading frame."]),
    make("Class 12","Evolution",
      "Explain evidence for evolution, natural selection, variation, genetic drift, gene flow and population-level frequency change.",
      [
        ["Evidence and common ancestry","Fossil succession provides historical evidence; homologous structures support common ancestry; analogous structures may arise through convergent adaptation. Embryological, biogeographical and molecular comparisons provide different evidence. No single trait should be used in isolation when multiple lines of evidence are available."],
        ["Sources of variation","Mutation introduces new alleles; recombination and independent assortment rearrange existing alleles; gene flow moves alleles among populations; genetic drift changes frequencies by chance. Variation is required for selection but not every variation affects fitness."],
        ["Natural selection and adaptation","Natural selection occurs when heritable differences lead to differential reproductive success in a given environment. Fitness is relative contribution to future generations, not strength or lifespan alone. Adaptation is a population-level result across generations. A trait beneficial in one environment may be neutral or harmful in another."],
        ["Hardy-Weinberg principle and speciation","For two alleles p+q=1 and equilibrium genotype frequencies p²+2pq+q²=1 under large population, random mating and absence of key evolutionary forces. Departures may reflect selection, drift, mutation, migration or non-random mating. Speciation can occur as gene flow decreases and reproductive isolation evolves."]
      ],
      [{label:"Hardy-Weinberg",meaning:"p+q=1; genotype proportions p²+2pq+q²=1 under model assumptions.",trap:"Phenotype frequency is not always allele frequency."},{label:"Genetic drift",meaning:"Random allele-frequency changes due to sampling effects.",trap:"Especially strong in small populations."}],
      [{title:"Hardy-Weinberg example",steps:["If recessive phenotype frequency q²=0.09 in the simplest model, q=0.3.","p=1−q=0.7.","Heterozygote frequency 2pq=2×0.7×0.3=0.42.","State the model assumptions; real populations may depart from equilibrium." ]},{title:"Explain selection",steps:["Describe heritable variation before selection.","Identify the environmental pressure.","Connect variation to differential survival/reproduction.","Explain how frequency can change over generations, not because individuals intentionally change." ]}],
      ["Saying an individual evolves because it needs to.","Confusing q² with q.","Treating fitness as physical strength.","Assuming selection always increases population size."],
      ["NEET focus: evidence types, forces changing allele frequencies and Hardy-Weinberg calculations."],
      ["What assumptions support Hardy-Weinberg equilibrium?","How is genetic drift different from selection?","Why is fitness environment-dependent?"],
      ["Gene flow: allele movement between populations.","Genetic drift: random frequency change.","Homologous structure: shared evolutionary origin."]),
    make("Class 12","Human Health and Disease",
      "Compare innate/adaptive immunity, immune cells, pathogens, vaccines, common diseases and antimicrobial resistance.",
      [
        ["Innate and adaptive immunity","Innate defence includes physical/chemical barriers, phagocytes, inflammation and other broad responses. Adaptive immunity uses antigen-specific B and T lymphocytes and may establish memory. Antibodies bind particular antigen features; cell-mediated responses include T-cell functions. Immune protection is not simply an all-or-none state."],
        ["Antibodies and immune memory","B cells can become plasma cells that secrete antibodies; memory B/T cells can support faster responses after later exposure. Vaccines expose the immune system to an antigen or antigen-encoding instruction in a controlled manner. Protection differs by pathogen, vaccine, schedule and host factors."],
        ["Pathogens and transmission","Disease agents include viruses, bacteria, protozoa, fungi and helminths; they differ in structure and replication. Routes can include droplets, contaminated food/water, vectors, blood, sexual contact and direct contact. Prevention should target the relevant route with sanitation, vaccination, vector control, barrier methods or clinical care."],
        ["Treatment and resistance","Antibiotics act on susceptible bacteria through specific mechanisms; they do not directly treat viral infections. Overuse or incorrect use favours resistant microbial populations. Symptoms alone often cannot distinguish pathogens; testing and qualified healthcare are important for diagnosis and treatment."]
      ],
      [{label:"Innate immunity",meaning:"Broad first-line defences and inflammatory/cellular responses.",trap:"It is not the same as 'no immune specificity at all' in every mechanism."},{label:"Antibody",meaning:"Immunoglobulin that binds a specific antigen feature.",trap:"Antibodies are not the only arm of adaptive immunity."},{label:"Vaccination",meaning:"Controlled immune priming that can generate memory.",trap:"Protection is not always absolute."}],
      [{title:"Explain a secondary response",steps:["First exposure activates antigen-specific lymphocytes.","Some activated cells form memory populations.","A later exposure can recruit memory cells more rapidly.","The response may be faster/stronger, although protection varies." ]},{title:"Select a prevention route",steps:["Identify the pathogen/transmission route supplied.","Choose a targeted prevention action, such as safe water or vector control.","Separate prevention from diagnosis/treatment.","Avoid saying a single intervention stops every route." ]}],
      ["Saying antibiotics treat viruses directly.","Treating all immunity as antibody-only.","Claiming vaccines guarantee zero infection.","Confusing pathogen with disease or transmission route."],
      ["NEET focus: immunity types, cell roles, vaccines, pathogens and prevention terminology."],
      ["What is immune memory?","Why do antibiotics not directly treat viruses?","What is one route-specific prevention measure?"],
      ["Antigen: structure recognised by an immune response.","Phagocyte: cell that engulfs/processes particles or microbes.","Antimicrobial resistance: ability of a microbe to survive a drug that previously inhibited it."]),
    make("Class 12","Microbes in Human Welfare",
      "Understand microbial uses in food, industry, sewage treatment, biogas, biocontrol and biofertiliser systems.",
      [
        ["Food and industrial products","Microbes ferment food components and produce acids, enzymes, alcohols, antibiotics and other products. Yield depends on strain, nutrient supply, oxygen, temperature, pH and process conditions. Curd formation uses lactic-acid bacteria under suitable conditions; yeasts support baking and alcoholic fermentation."],
        ["Sewage treatment","Primary treatment removes settleable/physical material; secondary treatment relies on microbial oxidation of organic matter. Microbial flocs reduce organic load and lower BOD after effective treatment. Sludge may then undergo anaerobic digestion. BOD is a measure associated with oxygen required to biologically degrade organic matter, not a direct measure of pathogen count."],
        ["Biogas and waste management","Anaerobic microbial communities, including methanogens, convert organic waste into methane-rich biogas. Conditions and feedstock affect yield. Methane is combustible and systems need safe handling; digestate also requires management. Waste-to-energy links treatment with resource recovery."],
        ["Biocontrol and biofertiliser","Biocontrol organisms/products suppress pests or pathogens under suitable conditions. Biofertilisers use beneficial microbes to fix nitrogen or improve nutrient availability. They can complement sustainable agriculture but are not a universal replacement for all inputs; matching the organism to crop, soil and environment matters."]
      ],
      [{label:"BOD",meaning:"Biochemical oxygen demand linked to biodegradation of organic material in water.",trap:"Higher BOD can mean greater oxygen depletion risk."},{label:"Methanogens",meaning:"Anaerobic microbes producing methane in biogas systems.",trap:"They function under oxygen-limited/anaerobic conditions."}],
      [{title:"Explain secondary sewage treatment",steps:["Aeration supports aerobic microbial communities/flocs.","Microbes consume/oxidise organic matter.","The resulting organic load and BOD decrease when treatment is effective.","Sludge handling and anaerobic digestion are subsequent treatment steps." ]},{title:"Match a microbial product",steps:["Identify the target outcome: food fermentation, industrial compound, waste treatment or crop support.","Match the microbe/process and relevant metabolism.","State the environmental conditions required.","Avoid treating all microbes as interchangeable." ]}],
      ["Confusing BOD with dissolved oxygen itself.","Calling anaerobic digestion aerobic.","Treating biocontrol as universally effective.","Ignoring strain and condition effects in industrial production."],
      ["NEET focus: process sequence, BOD meaning, microbe/product links and biocontrol/biofertilisers."],
      ["What does BOD indicate?","Why are methanogens associated with anaerobic conditions?","How do biofertilisers help plants?"],
      ["BOD: biochemical oxygen demand.","Biogas: combustible gas mixture from anaerobic digestion.","Biofertiliser: microbial preparation improving nutrient availability."]),
    make("Class 12","Biotechnology: Principles and Processes",
      "Trace recombinant DNA workflows from cutting and joining DNA to vectors, cloning, PCR, electrophoresis and expression.",
      [
        ["Core principles","Biotechnology uses biological systems to make or modify products/processes. Genetic engineering manipulates DNA, while bioprocess engineering grows organisms/cells under controlled production conditions. The workflow must distinguish a designed construct, successful transfer, confirmed insertion, gene expression and final product quality."],
        ["Restriction enzymes, ligase and vectors","Restriction endonucleases recognise specific DNA sequences and cut DNA; DNA ligase joins compatible ends. Vectors carry DNA into host cells and need suitable replication/selection features in the chosen system. A plasmid is a common vector type, but not every DNA molecule is automatically a useful vector."],
        ["PCR, gel electrophoresis and probes","PCR amplifies a target sequence using template, primers, nucleotides and a thermostable polymerase through denaturation, annealing and extension cycles. Gel electrophoresis separates nucleic-acid fragments by migration through a matrix; smaller fragments often travel farther under comparable conditions. Probes/sequence analysis can help verify identity."],
        ["Host expression and biosafety","A host may replicate inserted DNA and/or express a protein if regulatory and coding elements are compatible. Expression requires folding, processing and purity checks where relevant. Controls help identify contamination and nonspecific amplification. Biosafety, containment, ethical review and environmental consideration form part of responsible application."]
      ],
      [{label:"Restriction endonuclease",meaning:"Cuts DNA at recognised sequence sites.",trap:"Ligase joins DNA; it does not cut it."},{label:"PCR",meaning:"Amplifies a selected DNA segment using primers and cycles.",trap:"Primers define the target boundaries."},{label:"Vector",meaning:"Carries genetic material into a host system.",trap:"Insertion and expression must be separately verified."}],
      [{title:"Tool-to-task matching",steps:["Need to cut DNA at a sequence? Restriction endonuclease.","Need to join compatible ends? DNA ligase.","Need many copies of a chosen region? PCR.","Need to separate fragments? Gel electrophoresis.","Need to deliver DNA into a host? A suitable vector." ]},{title:"Interpret PCR result",steps:["Identify the expected product size.","Compare sample and controls on the gel.","A matching band supports expected-size amplification but does not always confirm sequence identity.","Consider contamination, nonspecific products and confirmatory methods." ]}],
      ["Confusing ligase and restriction enzyme roles.","Saying PCR separates fragments instead of amplifying them.","Assuming a plasmid's presence guarantees gene expression.","Ignoring positive/negative controls."],
      ["NEET focus: enzyme names, vector parts, PCR cycle order and fragment separation logic."],
      ["What do primers determine in PCR?","How do ligase and restriction enzymes differ?","Why is a control lane important?"],
      ["Recombinant DNA: DNA assembled from sources/sequences under a defined workflow.","Primer: short sequence initiating polymerase synthesis.","Vector: DNA vehicle used to carry an insert."]),
    make("Class 12","Biotechnology and Its Applications",
      "Connect recombinant products, transgenic organisms, molecular diagnosis, gene therapy, biopiracy and biosafety to applications.",
      [
        ["Medical applications","Recombinant DNA systems can produce proteins used as medicines, such as selected hormones/therapeutic proteins. Molecular diagnosis may detect DNA/RNA or antibodies depending on the test. A diagnostic test's sensitivity and specificity are properties of its performance; interpreting a positive result also depends on prevalence and clinical context."],
        ["Transgenic organisms and crops","Transgenic organisms contain intentionally introduced genetic material. Crop traits may include pest resistance, altered nutrition or tolerance to specific stresses, but real-world performance depends on gene, environment and management. Risk assessment considers food safety, gene flow, effects on non-target organisms and resistance evolution."],
        ["Gene therapy and molecular tools","Gene therapy aims to address disease by introducing/modifying genetic material in selected cells; delivery, immune response, expression and long-term safety are major challenges. A successful experiment requires evidence that the intended genetic change occurred and produces a beneficial functional result."],
        ["Ethics, biosafety and ownership","Biosafety assessment evaluates intended and unintended effects; ethics includes consent, fair benefit-sharing and limits on experiments. Biopiracy refers to unauthorised use/appropriation of biological resources or traditional knowledge without appropriate permission/benefit sharing. Innovation should account for local communities, regulation and environmental effects."]
      ],
      [{label:"Transgenic organism",meaning:"Organism carrying intentionally introduced genetic material.",trap:"A trait's presence does not guarantee benefit in every environment."},{label:"Gene therapy",meaning:"Approach aiming to treat disease through genetic material/cell modification.",trap:"Delivery and safety are major considerations."}],
      [{title:"Evaluate a crop application",steps:["State the introduced trait and its intended mechanism.","Identify the target problem and supporting evidence.","Consider non-target effects, resistance evolution and gene flow.","Distinguish potential benefits from outcomes that require testing." ]},{title:"Interpret a diagnostic test",steps:["Identify what the test detects—pathogen sequence, antibody or another marker.","Use the stated sensitivity/specificity data if supplied.","Consider prevalence/base rate for post-test probability.","Do not equate a positive screening result with complete clinical diagnosis in every context." ]}],
      ["Claiming every transgenic crop is risk-free or inherently harmful.","Treating a screening test as perfect.","Confusing gene therapy with simple vaccination.","Ignoring consent and benefit-sharing in biosafety/ethics questions."],
      ["NEET focus: product/method matching, transgenic traits, gene-therapy logic and biopiracy/biosafety terminology."],
      ["What is the purpose of a transgenic trait?","Why does prevalence affect interpretation of a positive result?","What does biopiracy mean?"],
      ["Transgenic: containing introduced genetic material.","Gene therapy: genetic intervention intended to treat disease.","Biosafety: practices and assessments limiting biological risks."]),
    make("Class 12","Organisms and Populations",
      "Explain environmental responses, population attributes, growth curves and ecological interactions through fitness and resource availability.",
      [
        ["Environmental responses","Temperature, water, salinity and resource availability affect organism performance. Conformers' internal conditions vary with the environment; regulators maintain selected conditions at an energy cost. Organisms can migrate or enter dormancy when conditions are unfavourable. Acclimatisation is an individual's adjustment, whereas evolution involves heritable population change across generations."],
        ["Population attributes","Density, age structure, natality, mortality, immigration and emigration describe populations, not single individuals. Population change over an interval equals births plus immigration minus deaths and emigration. Age pyramids help infer potential growth; dispersion may be clumped, uniform or random depending on resources and interactions."],
        ["Exponential and logistic growth","Exponential growth produces a J-shaped curve when resources are effectively unlimited; dN/dt=rN in the simple model. Logistic growth includes carrying capacity K, dN/dt=rN(1−N/K), and approaches an S-shaped curve. Carrying capacity can change with habitat or environment and should not be treated as a fixed universal constant."],
        ["Species interactions","Competition tends to harm both competitors when resources limit them; predation benefits predator and harms prey; parasitism benefits parasite at host cost; mutualism benefits both; commensalism benefits one while the other has little measurable effect. The effect pair can be written +/−/0, but explain the mechanism and context."]
      ],
      [{label:"Population change",meaning:"Births + immigration − deaths − emigration over the stated interval.",trap:"Use consistent time units and population denominator."},{label:"Logistic model",meaning:"Growth slows as N approaches carrying capacity K.",trap:"K can change as conditions change."}],
      [{title:"Calculate population change",steps:["Start with 120 individuals, 18 births, 7 deaths, 5 immigrants and 4 emigrants.","Final count=120+18−7+5−4=132.","Net change=+12.","If rates rather than counts are given, calculate each rate over the same interval." ]},{title:"Classify an interaction",steps:["Identify each species' benefit/harm/neutral outcome.","Competition: −/−; predation: +/−; mutualism: +/+; commensalism: +/0 in the standard model.","Check the actual scenario before assigning symbols.","Explain how resource use or interaction leads to the effect." ]}],
      ["Calling acclimatisation evolution.","Assuming K stays constant in a changing environment.","Treating a population attribute as an individual attribute.","Classifying an interaction from one species' perspective only."],
      ["NEET focus: growth curves, age structures, environmental response strategies and interaction sign pairs."],
      ["How do exponential and logistic growth differ?","Which factors increase population size?","What does +/0 represent in interaction notation?"],
      ["Carrying capacity: population size supported under specified conditions.","Conformer: organism with internal conditions varying with environment.","Natality: birth rate in a population."]),
    make("Class 12","Ecosystem",
      "Connect productivity, decomposition, trophic levels, energy flow, ecological pyramids and nutrient cycling.",
      [
        ["Productivity and components","An ecosystem includes biotic communities and abiotic environment interacting as a system. Gross primary productivity is total photosynthetic production; net primary productivity subtracts plant respiration. Consumers depend directly or indirectly on producers, and decomposers break down dead organic material and recycle nutrients."],
        ["Decomposition","Dead organic matter passes through fragmentation, leaching, catabolism, humification and mineralisation processes in the standard description. Temperature, moisture, oxygen, litter chemistry and decomposer communities influence rate. Nutrient-rich litter often decomposes faster than resistant lignin-rich material under similar conditions."],
        ["Energy flow and trophic levels","Energy enters mainly through producers and moves through feeding relationships; a portion is lost as heat/metabolism at each transfer. Nutrients cycle, but energy flows through and dissipates. The approximate 10% transfer rule is an educational simplification, not a universal constant."],
        ["Pyramids and cycles","Energy pyramids are upright because energy available tends to decrease at higher trophic levels; biomass/number pyramids can have different shapes. Carbon, nitrogen and phosphorus cycle through living and non-living reservoirs. Explain the process that moves material between reservoirs instead of merely listing reservoirs."]
      ],
      [{label:"NPP = GPP − respiration",meaning:"Net primary productivity after autotroph respiration.",trap:"GPP and NPP are not the same."},{label:"Energy flow",meaning:"One-way transfer through trophic levels with losses as heat.",trap:"Matter cycles; energy does not cycle in the same way."}],
      [{title:"Compute NPP",steps:["GPP is 2,400 energy units over a stated area/time; respiration is 900 units.","NPP=GPP−R=1,500 units.","State the same area/time unit as the inputs.","A consumer-level energy amount is not calculated directly from GPP without a transfer model." ]},{title:"Energy-transfer estimate",steps:["Producers contain 10,000 units in a simplified rule-of-thumb problem.","A 10% estimate would give primary consumers about 1,000 and secondary consumers about 100.","Label as an illustrative approximation.","Real ecological efficiency varies with food quality, assimilation and metabolism." ]}],
      ["Calling energy cyclic like nutrients.","Confusing GPP and NPP.","Treating 10% transfer as a fixed universal law.","Assuming every pyramid type must be upright."],
      ["NEET focus: productivity, decomposition order, trophic transfer and carbon/nitrogen cycles."],
      ["How is NPP calculated?","Why is an energy pyramid upright?","Name two factors affecting decomposition."],
      ["GPP: total primary production.","NPP: production remaining after autotroph respiration.","Mineralisation: release of inorganic nutrients from organic matter."]),
    make("Class 12","Biodiversity and Conservation",
      "Explain genetic/species/ecosystem diversity, geographic patterns, ecosystem services, extinction threats and conservation.",
      [
        ["Levels and patterns","Biodiversity occurs at genetic, species and ecosystem levels. Species richness counts species; evenness describes how individuals are distributed among them. Richness often varies with area, latitude, habitat complexity and evolutionary history, but a pattern should be interpreted using its scale and data rather than treated as exceptionless."],
        ["Importance and services","Biodiversity supports food webs, pollination, soil formation, nutrient cycles, climate/water regulation and cultural/economic values. Ecosystem services can be direct or indirect and often depend on interactions among species. Loss of a keystone or functionally important species can have disproportionate effects compared with its abundance."],
        ["Threats and extinction","Habitat loss/fragmentation, invasive species, overexploitation, pollution and climate change contribute to declines. Extinction is permanent loss of a lineage; local extinction differs from global extinction. Causes often interact, so conservation may need habitat protection, threat removal and monitoring."],
        ["In situ and ex situ conservation","In situ conservation protects species in their natural habitat through reserves and protected areas. Ex situ conservation includes seed/gene banks, botanical gardens, zoos and captive breeding. Each approach has limits: ex situ populations may lose genetic diversity or adaptation, while habitat protection may not stop every threat. Recovery is strongest when linked to habitat/ecosystem needs."]
      ],
      [{label:"In situ",meaning:"Conservation within natural habitat.",trap:"Protected-area designation alone does not remove every threat."},{label:"Ex situ",meaning:"Conservation outside natural habitat, such as seed banks/captive breeding.",trap:"It complements rather than universally replaces habitat protection."}],
      [{title:"Classify a conservation measure",steps:["Identify whether the species remains in its habitat.","Natural-habitat reserve/restoration is in situ.","Seed bank, captive breeding or botanical collection is ex situ.","Explain the goal and limitation in the given context." ]},{title:"Interpret biodiversity data",steps:["Separate species richness from abundance/evenness.","Compare the same sampling effort/area where possible.","Identify the measured level—genetic, species or ecosystem.","Avoid concluding that one high count proves ecosystem health in every respect." ]}],
      ["Treating richness and evenness as identical.","Confusing local disappearance with global extinction.","Assuming ex situ conservation permanently solves habitat threats.","Ignoring invasive species or habitat fragmentation."],
      ["NEET focus: threats, biodiversity levels, ecosystem services, in situ/ex situ examples."],
      ["What is the difference between richness and evenness?","Give one in situ and one ex situ method.","Name two causes of biodiversity loss."],
      ["Species richness: number of species in a defined area.","Fragmentation: division of continuous habitat into smaller isolated patches.","Keystone species: species with a disproportionately large ecological effect."]),
    make("Class 12","Environmental Issues",
      "Explain air/water pollution, waste management, greenhouse effect, ozone depletion, eutrophication and sustainable mitigation.",
      [
        ["Air pollution and climate","Combustion, industrial processes, transport and biomass burning emit pollutants with health/ecosystem effects. Greenhouse gases absorb outgoing infrared radiation and contribute to warming; the natural greenhouse effect makes Earth habitable, while increased gas concentrations alter energy balance. Distinguish global climate forcing from local air pollution."],
        ["Ozone depletion and UV","Stratospheric ozone absorbs much harmful ultraviolet radiation. Certain chlorine/bromine-containing compounds can catalytically destroy ozone after reaching the stratosphere. Ozone depletion increases UV exposure risks; it is distinct from the greenhouse effect even though some compounds influence both atmospheric chemistry and climate."],
        ["Water pollution and eutrophication","Excess nutrients can cause algal blooms; decomposition consumes dissolved oxygen and can create hypoxic zones. Untreated sewage raises organic load and BOD; industrial chemicals, pathogens and heavy metals create different risks. Control starts with source reduction and proper treatment rather than dilution alone."],
        ["Waste and sustainable response","Waste hierarchy prioritises prevention/reduction, reuse and recycling when safe; hazardous/biomedical waste requires dedicated handling. Sustainable mitigation combines technology, policy, monitoring and individual/community behaviour. Evaluate each proposed solution against pollutant source, scale, lifecycle impacts and equity."]
      ],
      [{label:"Greenhouse effect",meaning:"Atmospheric gases absorb/re-emit outgoing infrared radiation.",trap:"It is not the same mechanism as stratospheric ozone depletion."},{label:"Eutrophication",meaning:"Nutrient enrichment can cause blooms and oxygen depletion.",trap:"The oxygen decline often follows decomposition of biomass."},{label:"BOD",meaning:"Measure related to oxygen required to biodegrade organic matter in water.",trap:"BOD is not a direct pathogen count."}],
      [{title:"Trace eutrophication",steps:["Nutrient input increases from runoff/sewage.","Algal biomass may rise, then die or be consumed.","Microbial decomposition uses dissolved oxygen.","Low oxygen stresses/kills aquatic organisms; prevention targets nutrient inputs." ]},{title:"Compare atmospheric issues",steps:["Greenhouse effect changes heat retention through infrared absorption.","Ozone depletion reduces stratospheric UV shielding.","Identify the key pollutant/process in the prompt.","Select mitigation that acts on that cause rather than using a generic 'reduce pollution' response." ]}],
      ["Confusing greenhouse warming and ozone depletion.","Saying an algal bloom itself always lowers oxygen immediately; decomposition is a key step.","Assuming dilution alone treats pollution.","Treating recycling as preferable to preventing waste in every case."],
      ["NEET/CBSE focus: cause-effect chains, pollution types and targeted mitigation."],
      ["What causes oxygen depletion during eutrophication?","How does ozone protect life?","How is greenhouse warming different from ozone depletion?"],
      ["Eutrophication: nutrient enrichment with ecosystem effects.","Hypoxia: low dissolved oxygen.","Stratospheric ozone: ozone layer absorbing much incoming UV radiation."])
  ];

  const makeClass10Science = (chapter, intro, sections, facts, examples, mistakes, examFocus, recall, glossary) =>
    make("Class 10", chapter, intro, sections, facts, examples, mistakes, examFocus, recall, glossary, "Science");

  notes.push(
    makeClass10Science("Life Processes",
      "Explain nutrition, respiration, transport and excretion as linked life-maintenance systems in plants and animals.",
      [
        ["Nutrition and digestion","Autotrophs build organic food from inorganic raw materials using an external energy source; green plants use light for photosynthesis. Heterotrophs obtain organic nutrients from other organisms. In humans, ingestion, digestion, absorption, assimilation and egestion are different stages. Enzymes break large food molecules into smaller absorbable units; bile helps emulsify fats but is not itself a digestive enzyme."],
        ["Respiration and energy","Cellular respiration releases usable energy from organic molecules through controlled reactions. Aerobic respiration uses oxygen as the terminal electron acceptor in the overall pathway and usually yields much more ATP than anaerobic pathways. In yeast, anaerobic fermentation produces ethanol and carbon dioxide; in some animal cells, lactate can form under limited oxygen supply. Breathing exchanges gases; it is not the same as cellular respiration."],
        ["Transport in plants and animals","In plants, xylem conducts water and mineral ions from roots and phloem translocates organic solutes from source to sink. Transpiration can generate pull in xylem. In humans, the heart pumps blood through pulmonary and systemic circuits; arteries carry blood away from the heart and veins toward it, regardless of oxygenation exceptions. Capillaries provide exchange surfaces."],
        ["Excretion and homeostasis","Excretion removes metabolic wastes such as urea and helps control water/ion balance. Nephrons filter blood, reabsorb useful substances and secrete selected materials; the final urine composition differs from the initial filtrate. Plants do not have a human-like excretory organ system; wastes can be stored, released through stomata or lenticels, or removed with discarded parts. Homeostasis keeps internal conditions within workable ranges."]
      ],
      [{label:"Photosynthesis (simplified)",meaning:"CO₂ and water are converted to carbohydrate using light energy; oxygen released comes from water.",trap:"Do not reverse photosynthesis and respiration."},{label:"Arteries vs veins",meaning:"Arteries carry blood away from the heart; veins return it.",trap:"Do not classify by oxygen content alone."},{label:"Nephron",meaning:"Filtration plus selective reabsorption/secretion forms urine.",trap:"Filtered water and solutes are not all excreted."}],
      [{title:"Trace a food molecule",steps:["Food is digested into smaller absorbable molecules.","Small molecules cross the intestinal wall and enter circulation/lymph as applicable.","Cells assimilate nutrients for energy, synthesis or storage.","Undigested residues leave by egestion; metabolic waste leaves through excretory processes." ]},{title:"Trace oxygen",steps:["Ventilation moves air into alveoli.","Oxygen diffuses into blood and is mostly carried by haemoglobin.","Circulation delivers blood to tissues.","Oxygen diffuses into cells and supports cellular energy pathways." ]}],
      ["Calling breathing and respiration the same process.","Saying bile is an enzyme.","Assuming every artery carries oxygenated blood.","Treating glomerular filtrate as identical to final urine."],
      ["CBSE focus: draw and label alimentary canal, nephron, heart and transport tissues; compare plant/animal systems."],
      ["What is the difference between egestion and excretion?","What does xylem transport?","Why is absorption not the same as digestion?"],
      ["Assimilation: use/incorporation of absorbed nutrients.","Transpiration: water-vapour loss from aerial plant parts.","Homeostasis: regulation of internal conditions."]),
    makeClass10Science("Control and Coordination",
      "Compare nervous and hormonal communication and explain reflexes, plant tropisms and major animal coordination structures.",
      [
        ["Nervous system signalling","Neurons carry electrical signals through changes in membrane potential. Dendrites receive input, the cell body integrates it and the axon conducts impulses. At a synapse, a chemical neurotransmitter can cross the gap and affect the next cell. A reflex arc produces a rapid response through receptor, sensory neuron, CNS connection, motor neuron and effector."],
        ["Brain, spinal cord and response","The central nervous system includes brain and spinal cord; peripheral nerves connect it to receptors and effectors. Different brain regions contribute to coordination, balance, voluntary action and vital automatic functions. A reflex is coordinated and stereotyped, but does not mean the brain never receives information about it."],
        ["Endocrine control","Hormones are chemical signals transported to target cells that have suitable receptors. Insulin helps reduce blood glucose, while glucagon acts in the opposite direction in the standard regulation model. Thyroxine influences metabolic activity and requires iodine for synthesis. Adrenaline prepares the body for rapid action; hormone levels are controlled by feedback."],
        ["Plant responses","Plants do not use a nervous system like animals, but they coordinate responses through growth, cell turgor and chemical signals. Phototropism is directional growth in response to light; gravitropism responds to gravity. Auxin distribution can drive differential growth, bending a shoot toward light. Nastic movements do not depend on stimulus direction in the same way as tropisms."]
      ],
      [{label:"Reflex arc",meaning:"Receptor → sensory neuron → CNS connection → motor neuron → effector.",trap:"A reflex is fast and stereotyped but still coordinated by neural tissue."},{label:"Hormone target",meaning:"A cell responds when it has the appropriate receptor machinery.",trap:"Blood exposure alone does not make every cell respond."},{label:"Phototropism",meaning:"Directional plant growth response to light.",trap:"Tropism is directional; nastic movement is not defined by stimulus direction."}],
      [{title:"Compare response pathways",steps:["A nervous response uses electrochemical signalling through neurons and synapses.","A hormone response uses chemical messenger transport and receptor binding.","Nervous responses are often faster and more targeted; endocrine responses may be longer-lasting.","Do not state an absolute timing rule for every pathway." ]},{title:"Explain shoot bending",steps:["Light arrives mainly from one direction.","Auxin distribution differs across the shoot sides in the standard model.","Cells on one side elongate differently from the other.","Differential growth bends the shoot toward light." ]}],
      ["Treating plant responses as animal reflexes.","Confusing endocrine glands and target tissues.","Saying all hormones act on every cell.","Mixing phototropism with nastic movement."],
      ["CBSE focus: reflex-arc diagrams, neuron labelling, endocrine hormone-function links and tropism explanations."],
      ["What is the role of a synapse?","How does a hormone select target cells?","How does phototropism differ from a nastic movement?"],
      ["Effector: muscle/gland producing a response.","Synapse: junction through which cells communicate.","Tropism: directional growth response to a stimulus."]),
    makeClass10Science("How Do Organisms Reproduce?",
      "Compare asexual and sexual reproduction and link reproductive structures to variation, fertilisation and development.",
      [
        ["Asexual reproduction","Asexual reproduction uses one parent and does not involve fusion of gametes. Binary fission, budding, fragmentation, spore formation and vegetative propagation are distinct modes. Offspring are usually genetically very similar to the parent apart from mutations, allowing rapid multiplication but producing less new variation from one generation to the next."],
        ["Sexual reproduction and variation","Sexual reproduction involves formation of gametes and their fusion at fertilisation, producing a zygote. Meiosis reduces chromosome number in gametes; fertilisation restores the species' characteristic ploidy. Recombination and independent assortment create variation, which can support population adaptability across changing environments."],
        ["Plant reproduction","Flowers contain reproductive structures; anthers produce pollen containing the male gametophyte and ovules contain the female gametophyte/embryo sac. Pollination transfers pollen to a stigma; pollen-tube growth and fertilisation occur after compatible pollination. After fertilisation, the ovule typically becomes a seed and the ovary becomes fruit."],
        ["Human reproductive development","Human reproductive systems produce sperm and ova; fertilisation usually occurs in the oviduct and early development proceeds through cleavage to implantation. Placental tissues support exchange during pregnancy. Puberty involves hormonal changes and maturation of reproductive function. Reproductive health includes informed choices, contraception, STI prevention and access to qualified care."]
      ],
      [{label:"Asexual vs sexual",meaning:"Asexual: no gamete fusion; sexual: gamete formation and fusion.",trap:"Asexual reproduction is not the same as no cell division."},{label:"Pollination",meaning:"Transfer of pollen to a receptive stigma.",trap:"Pollination occurs before fertilisation."},{label:"Ovule/ovary outcomes",meaning:"Ovule typically forms seed; ovary typically forms fruit.",trap:"Keep the structures distinct."}],
      [{title:"Order angiosperm reproduction",steps:["Anther produces pollen; ovule contains the embryo sac.","Pollination transfers compatible pollen to the stigma.","Pollen tube delivers male gametes to the ovule.","Fertilisation precedes seed and fruit development." ]},{title:"Explain variation",steps:["Meiosis produces genetically varied haploid gametes.","Fertilisation combines gametes from two parents.","New allele combinations can differ among siblings.","Variation is a source for selection across generations, not a guarantee that each variation is beneficial." ]}],
      ["Confusing pollination and fertilisation.","Claiming asexual reproduction never involves cell division.","Swapping seed and fruit origins.","Saying every variation improves survival."],
      ["CBSE focus: modes of reproduction, labelled reproductive diagrams, menstruation/fertilisation basics and seed/fruit development."],
      ["What is the difference between asexual and sexual reproduction?","What happens during pollination?","Why can sexual reproduction increase variation?"],
      ["Gamete: haploid reproductive cell.","Fertilisation: fusion of gametes/nuclei.","Vegetative propagation: new plants form from vegetative parts."]),
    makeClass10Science("Heredity and Evolution",
      "Connect inheritance patterns and genetic variation to Mendel's crosses, sex determination and population-level evolution.",
      [
        ["Genes, alleles and traits","Genes carry information contributing to traits; alleles are different versions of a gene. An individual inherits alleles from parents, and the visible phenotype may depend on dominance, multiple genes and environment. Dominant does not mean common, stronger or more advantageous; it describes expression in a particular heterozygous context."],
        ["Mendelian inheritance","In a simple monohybrid Aa×Aa cross with complete dominance, expected genotypes are 1 AA:2 Aa:1 aa and phenotypes are 3 dominant:1 recessive. These are probabilities, not guaranteed counts in every small family. A Punnett square lists gamete combinations and makes the assumptions visible."],
        ["Sex determination and variation","Human sex determination is often introduced using XX and XY chromosomes: ova carry X, while sperm carry X or Y in the standard model. Fertilisation determines the combination; neither parent should be blamed for a child's sex. Mutations and recombination create variation, while selection and other population processes change trait/allele frequencies over generations."],
        ["Evolution and evidence","Evolution is heritable population change over generations, not an individual changing because it needs to. Fossils, homologous structures and molecular similarities support evolutionary relationships. Acquired changes during an individual's life are not usually inherited genetically in the basic model. Natural selection changes frequencies when heritable variants differ in reproductive success."]
      ],
      [{label:"Aa×Aa",meaning:"Expected genotype ratio 1:2:1; phenotype 3:1 under complete dominance.",trap:"Ratio assumes the stated Mendelian model."},{label:"Evolution",meaning:"Heritable change in populations over generations.",trap:"Individual acclimatisation is not the same as evolution."}],
      [{title:"Punnett square",steps:["Each Aa parent makes A and a gametes with probability 1/2.","Combine four equally likely gamete pairs: AA, Aa, aA and aa.","Genotypes give 1/4 AA, 1/2 Aa and 1/4 aa.","With complete dominance, three of four show the dominant phenotype expectation." ]},{title:"Evidence and inference",steps:["Identify whether evidence is fossil, anatomical, embryological or molecular.","State what relationship or change the evidence supports.","Avoid claiming a single fossil proves every step of a lineage.","Compare multiple independent evidence types where available." ]}],
      ["Calling dominant alleles always more common.","Treating Punnett ratios as exact for a tiny family.","Saying an individual evolves genetically because it needs to.","Blaming a parent for sex determination."],
      ["CBSE/JEE/NEET preparation: show gametes, genotype and phenotype separately; distinguish inheritance from evolution."],
      ["What does dominance mean?","What genotype ratio follows from Aa×Aa?","How does evolution differ from individual acclimatisation?"],
      ["Allele: gene variant.","Genotype: allele combination.","Phenotype: observable trait influenced by genotype and environment."]),
    makeClass10Science("Our Environment",
      "Explain food chains, trophic levels, energy transfer, decomposers, nutrient cycling and the effects of persistent pollutants.",
      [
        ["Ecosystem components","An ecosystem includes producers, consumers, decomposers and abiotic factors such as light, water, minerals and temperature. Producers convert external energy into chemical energy; consumers obtain energy by feeding; decomposers break down organic material and return nutrients to the environment. Matter cycles through ecosystems, while energy flow is one-way and dissipates as heat."],
        ["Food chains and trophic levels","A food chain represents energy transfer through feeding relationships; a food web combines many chains. Producers occupy the first trophic level, herbivores commonly the second and carnivores higher levels. Real food webs are more complex than a single chain because organisms may feed at multiple levels."],
        ["Energy transfer and decomposers","Only a portion of energy in one trophic level is available to the next because organisms use energy for metabolism, movement and maintenance and lose heat. The approximate 10% rule is a useful classroom simplification, not a fixed law for every ecosystem. Decomposers process dead organisms and wastes, returning inorganic nutrients for reuse."],
        ["Biomagnification and waste","Persistent non-biodegradable chemicals can accumulate in organisms and reach higher concentrations at higher trophic levels in biomagnification. Biodegradable waste can be processed by decomposers, but excessive input can overwhelm the system. Reduce waste at source, reuse materials and dispose of hazardous substances through safe collection routes."]
      ],
      [{label:"Energy flow",meaning:"Energy moves through feeding levels and is lost as heat; nutrients recycle.",trap:"Do not say energy is recycled just like matter."},{label:"Biomagnification",meaning:"Increasing concentration of a persistent pollutant at higher trophic levels.",trap:"Persistence and food-chain transfer are important."}],
      [{title:"Energy-chain estimate",steps:["If producers contain 10,000 energy units, a simplified 10% transfer estimate gives about 1,000 to primary consumers.","A further illustrative 10% gives about 100 to secondary consumers.","State this as a model estimate; efficiencies vary.","The main principle is declining available energy at higher trophic levels." ]},{title:"Trace a pollutant",steps:["A persistent chemical enters the food web.","It accumulates in organisms and is passed through feeding.","Higher trophic levels may receive greater concentrations over time.","Prevention targets source release and persistence, not only litter appearance." ]}],
      ["Treating all wastes as biodegradable.","Saying energy cycles through an ecosystem.","Using 10% transfer as a precise universal constant.","Confusing bioaccumulation in one organism with biomagnification through trophic levels."],
      ["CBSE focus: food-web diagrams, trophic levels, decomposers, persistent pollutants and waste management."],
      ["What is a decomposer's role?","Why does available energy decline up a food chain?","What is biomagnification?"],
      ["Trophic level: feeding position.","Decomposer: organism that breaks down dead organic material.","Persistent pollutant: chemical that resists breakdown and can accumulate."]),
    makeClass10Science("Sustainable Management of Natural Resources",
      "Evaluate conservation of forests, water, fossil fuels and biodiversity through resource stewardship and stakeholder participation.",
      [
        ["Sustainability","Sustainable use satisfies present needs without undermining the ability of future generations to meet their needs. Natural resources differ in regeneration speed, distribution and ecological role; a renewable resource can still be depleted when harvest exceeds renewal or damages the system supporting it."],
        ["Forests and stakeholders","Forests provide biodiversity, soil protection, water-cycle regulation and livelihoods. Management affects local communities, governments, industry and conservation groups. Excluding all local use can undermine livelihoods and compliance; unregulated extraction can also damage ecosystem function. Effective decisions account for ecological data and fair participation."],
        ["Water management","Rainwater harvesting captures precipitation for storage or groundwater recharge. Watershed management uses soil/vegetation practices to slow runoff and reduce erosion. Large dams can support irrigation/electricity but may displace communities, alter rivers and affect sediment/ecosystems. Compare benefits, costs and alternatives for the specific site."],
        ["Energy and consumer choice","Fossil fuels contain stored chemical energy but their combustion emits pollutants and greenhouse gases. Energy efficiency reduces resource demand; cleaner sources reduce certain emissions but still have material, land and reliability considerations. Responsible management combines individual choices, infrastructure, regulation and transparent impact evaluation."]
      ],
      [{label:"Sustainable use",meaning:"Use resources while maintaining ecological and future availability.",trap:"'Renewable' does not mean impossible to deplete."},{label:"Rainwater harvesting",meaning:"Collection/storage/recharge of precipitation.",trap:"Design must match local rainfall, soil and water quality."}],
      [{title:"Evaluate a resource proposal",steps:["Identify the resource, its regeneration rate and the proposed extraction/use.","List ecological, economic and social benefits/costs.","Identify who gains, who may be displaced and what alternatives exist.","Make a conclusion specific to the evidence and trade-offs." ]},{title:"Compare water strategies",steps:["Rainwater harvesting captures local precipitation.","Watershed practices slow runoff and reduce erosion.","Dams can store water but have river/ecosystem/social impacts.","Use local geography and community needs to evaluate the approach." ]}],
      ["Assuming renewable resources cannot run out.","Treating conservation as only a government task.","Comparing projects without considering local context.","Ignoring social costs while describing resource benefits."],
      ["CBSE focus: stakeholder roles, practical conservation methods and balanced evaluation of development options."],
      ["Why can a renewable resource still be depleted?","What is the purpose of watershed management?","Why should social impacts be included in conservation decisions?"],
      ["Watershed: land area draining to a common outlet.","Rainwater harvesting: capturing/recharging precipitation.","Sustainability: meeting needs while protecting future capacity."]
  ));

  window.KP_NCERT_CHAPTER_NOTES = (Array.isArray(window.KP_NCERT_CHAPTER_NOTES) ? window.KP_NCERT_CHAPTER_NOTES : []).concat(notes);
})();
